input.content:
:root {
  --green: #9be15d;
  --green-dim: #4f7a2a;
  --blue: #58a6d8;
  --gold: #f4c542;
  --red: #e0453b;
  --ink: #0b0d0f;
  --panel: rgba(10, 12, 14, 0.72);
  --font-ui: "Helvetica Neue", "Segoe UI", Roboto, Arial, sans-serif;
  --font-display: "Arial Black", Impact, "Franklin Gothic Heavy", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #07090a;
  color: #fff;
  font-family: var(--font-ui);
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

#app { position: relative; width: 100vw; height: 100vh; overflow: hidden; }

canvas#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.hidden { display: none !important; }

/* ---------------- HUD ---------------- */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 20;
  font-family: var(--font-ui);
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.8);
}

.hud-top-right {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  right: max(22px, env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.money {
  font-family: var(--font-display);
  font-size: 30px;
  letter-spacing: 1px;
  color: #d9f7c4;
  -webkit-text-stroke: 1px rgba(0, 0, 0, 0.55);
  transition: transform 0.15s ease;
}
.money.bump { transform: scale(1.14); color: #fff; }

.wanted {
  display: flex;
  gap: 4px;
  margin-bottom: 2px;
  padding: 2px 6px;
  background: rgba(0, 0, 0, 0.25);
  border-radius: 4px;
}
.wanted .star {
  font-size: 24px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.16);
  transition: color 0.2s ease, transform 0.2s ease;
}
.wanted .star.on { color: var(--gold); filter: drop-shadow(0 0 6px rgba(244, 197, 66, 0.8)); }
.wanted .star.flash { animation: starflash 0.7s infinite; }
@keyframes starflash { 50% { opacity: 0.15; } }

.radio-popup {
  margin-top: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  letter-spacing: 2px;
  color: #e8dfc0;
  background: rgba(8, 10, 12, 0.62);
  border: 1px solid rgba(232, 223, 192, 0.25);
  border-left: 3px solid var(--gold);
  padding: 6px 10px;
  border-radius: 2px;
  animation: radioIn 0.25s ease;
}
.radio-icon { font-size: 15px; color: var(--gold); }
@keyframes radioIn { from { opacity: 0; transform: translateX(12px); } }

.hud-left {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}

.area-name {
  font-family: var(--font-display);
  font-size: 13px;
  letter-spacing: 2.5px;
  color: rgba(255, 255, 255, 0.92);
  padding-left: 4px;
  text-shadow: 0 2px 8px #000;
}

.radar-wrap {
  position: relative;
  width: 198px;
  height: 198px;
  border-radius: 50%;
  overflow: hidden;
  background: #0a1210;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.65);
  border: 2px solid rgba(255, 255, 255, 0.72);
}
#radar { width: 100%; height: 100%; display: block; }
.radar-ring {
  position: absolute; inset: 0; border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.45);
  box-shadow: inset 0 0 32px rgba(0, 0, 0, 0.55);
  pointer-events: none;
}
.radar-n {
  position: absolute; top: 5px; left: 50%; transform: translateX(-50%);
  font-size: 10px; font-weight: 800; color: rgba(255, 255, 255, 0.75);
  letter-spacing: 1px;
}
.player-blip {
  position: absolute; top: 50%; left: 50%;
  width: 0; height: 0; transform: translate(-50%, -50%);
}
.player-blip::after {
  content: ""; position: absolute; left: -5px; top: -8px;
  border-left: 5px solid transparent; border-right: 5px solid transparent;
  border-bottom: 13px solid #fff;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.9));
}

.stat-bars { display: flex; flex-direction: column; gap: 3px; width: 198px; padding: 0 2px; }
.stat {
  height: 7px; background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 1px; overflow: hidden;
}
.stat .fill { height: 100%; width: 100%; transition: width 0.2s ease; }
.stat.health .fill { background: linear-gradient(90deg, #57b83f, #9be15d); }
.stat.armor .fill { background: linear-gradient(90deg, #2d6f9c, #6cc4f5); }
.stat.armor { height: 5px; }

.objective {
  position: absolute;
  bottom: max(26px, calc(env(safe-area-inset-bottom) + 16px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: min(560px, 60vw);
  padding: 9px 18px 9px 12px;
  background: linear-gradient(90deg, rgba(12, 15, 16, 0.88), rgba(12, 15, 16, 0.6));
  border-left: 3px solid var(--gold);
  border-radius: 2px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: #f1edde;
}
.objective-icon { color: var(--gold); font-size: 12px; }
.objective.complete { border-left-color: var(--green); }
.objective.complete .objective-icon { color: var(--green); }

.subtitle {
  position: absolute;
  bottom: 100px;
  left: 50%;
  transform: translateX(-50%);
  max-width: min(760px, 80vw);
  text-align: center;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.2px;
  color: #fff;
  background: rgba(0, 0, 0, 0.55);
  padding: 8px 18px;
  border-radius: 3px;
  text-shadow: 0 2px 8px #000;
  animation: subIn 0.2s ease;
}
@keyframes subIn { from { opacity: 0; transform: translate(-50%, 5px); } }

.notifications {
  position: absolute;
  top: max(20px, env(safe-area-inset-top));
  left: max(22px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 380px;
}
.note {
  background: rgba(9, 11, 13, 0.78);
  border-left: 3px solid var(--green);
  padding: 10px 14px;
  border-radius: 2px;
  animation: noteIn 0.3s ease;
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.note .note-title { font-size: 12px; font-weight: 800; letter-spacing: 1.6px; color: var(--green); }
.note .note-body { font-size: 12.5px; color: rgba(255, 255, 255, 0.8); margin-top: 3px; }
.note.money-note { border-left-color: var(--gold); }
.note.money-note .note-title { color: var(--gold); }
.note.police-note { border-left-color: var(--red); }
.note.police-note .note-title { color: #ff7a70; }
.note.out { opacity: 0; transform: translateX(-16px); }
@keyframes noteIn { from { opacity: 0; transform: translateX(-16px); } }

.hud-bottom-right {
  position: absolute;
  right: max(24px, env(safe-area-inset-right));
  bottom: max(22px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.weapon-hud {
  display: flex;
  align-items: center;
  gap: 12px;
  background: linear-gradient(90deg, rgba(8, 10, 12, 0.45), rgba(8, 10, 12, 0.8));
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-right: 3px solid rgba(255, 255, 255, 0.55);
  padding: 9px 14px;
  border-radius: 2px;
  min-width: 178px;
  justify-content: flex-end;
}
.weapon-icon { font-size: 20px; filter: grayscale(0.2); }
.weapon-meta { text-align: right; }
.weapon-name { font-size: 11px; font-weight: 800; letter-spacing: 1.8px; color: rgba(255, 255, 255, 0.65); }
.ammo { font-family: var(--font-display); font-size: 26px; line-height: 1; letter-spacing: 1px; }
.ammo .ammo-sep { font-size: 15px; color: rgba(255, 255, 255, 0.4); margin: 0 3px; }
.ammo #ammo-reserve { font-size: 16px; color: rgba(255, 255, 255, 0.55); }
.weapon-hud.low #ammo-mag { color: #ff877d; }

.speedo { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; }
.speedo-row { display: flex; align-items: baseline; gap: 5px; }
#speedo-num { font-family: var(--font-display); font-size: 40px; line-height: 0.9; letter-spacing: -1px; }
.speedo-unit { font-size: 10px; letter-spacing: 2px; color: rgba(255, 255, 255, 0.55); }
.speedo-bar { width: 150px; height: 4px; background: rgba(0, 0, 0, 0.55); border: 1px solid rgba(255, 255, 255, 0.15); overflow: hidden; }
#speedo-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #f4c542, #ff6b4a); transition: width 0.08s linear; }
.gear { position: absolute; right: 0; bottom: 0; font-size: 14px; font-weight: 800; color: var(--gold); }

.crosshair {
  position: absolute; top: 50%; left: 50%; width: 30px; height: 30px;
  transform: translate(-50%, -50%);
  opacity: 0.9;
  transition: transform 0.12s ease, opacity 0.2s ease;
}
.crosshair i {
  position: absolute; background: rgba(255, 255, 255, 0.95);
  box-shadow: 0 0 3px rgba(0, 0, 0, 0.9);
}
.crosshair i:nth-child(1) { left: 14px; top: 0; width: 1.5px; height: 8px; }
.crosshair i:nth-child(2) { left: 14px; bottom: 0; width: 1.5px; height: 8px; }
.crosshair i:nth-child(3) { top: 14px; left: 0; height: 1.5px; width: 8px; }
.crosshair i:nth-child(4) { top: 14px; right: 0; height: 1.5px; width: 8px; }
.crosshair b { position: absolute; left: 14px; top: 14px; width: 2px; height: 2px; background: #fff; border-radius: 50%; }
.crosshair.wide { transform: translate(-50%, -50%) scale(1.45); }
.crosshair.hit i { background: #ff5a4f; }
.crosshair.no-weapon { opacity: 0.3; }
.crosshair.hidden { display: none; }

.hitmarker {
  position: absolute; top: 50%; left: 50%; width: 26px; height: 26px;
  transform: translate(-50%, -50%) rotate(45deg);
  opacity: 0; pointer-events: none;
}
.hitmarker::before, .hitmarker::after {
  content: ""; position: absolute; background: #fff; box-shadow: 0 0 4px #000;
}
.hitmarker::before { left: 12px; top: 0; width: 2px; height: 26px; }
.hitmarker::after { top: 12px; left: 0; height: 2px; width: 26px; }
.hitmarker.show { animation: hitpop 0.22s ease; }
@keyframes hitpop { 0% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(0.7); } 100% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(1.2); } }

.damage-vignette {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(180, 10, 10, 0.55) 100%);
  transition: opacity 0.35s ease;
}
.damage-vignette.show { opacity: 1; transition: opacity 0.06s ease; }

.area-banner {
  position: absolute;
  top: 24%;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  opacity: 0;
  transition: opacity 0.6s ease;
  pointer-events: none;
}
.area-banner.show { opacity: 1; }
.area-banner .ab-name {
  font-family: var(--font-display);
  font-size: clamp(28px, 5vw, 54px);
  letter-spacing: 2px;
  color: #f6f2e6;
  text-transform: uppercase;
  -webkit-text-stroke: 1px rgba(0, 0, 0, 0.6);
}
.area-banner .ab-sub { font-size: 11px; letter-spacing: 5px; color: rgba(255, 255, 255, 0.7); margin-top: 4px; }

.big-message {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0.62));
  animation: bigIn 0.5s ease;
}
#big-title {
  font-family: var(--font-display);
  font-size: clamp(44px, 9vw, 108px);
  letter-spacing: 4px;
  color: #f8f4e6;
  text-shadow: 0 6px 30px rgba(0, 0, 0, 0.8);
}
#big-title.pass { color: #e9d58a; }
#big-sub { font-size: 22px; font-weight: 700; letter-spacing: 4px; color: var(--green); }
@keyframes bigIn { from { opacity: 0; transform: scale(1.04); } }

/* ---------------- Intro ---------------- */
.intro {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #05090c;
  transition: opacity 0.7s ease, visibility 0.7s;
}
.intro.out { opacity: 0; visibility: hidden; }
.intro-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 72% 30%, rgba(255, 166, 74, 0.4), transparent 52%),
    radial-gradient(ellipse at 20% 90%, rgba(28, 74, 80, 0.5), transparent 60%),
    linear-gradient(180deg, #121c26 0%, #2f2b33 45%, #0c1013 100%);
}
.intro-bg::after {
  content: "";
  position: absolute; inset: 0;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(0, 0, 0, 0.12) 3px 4px);
  mix-blend-mode: multiply;
  opacity: 0.4;
}
.intro-content {
  position: relative;
  z-index: 2;
  margin-left: clamp(24px, 8vw, 120px);
  width: min(660px, 82vw);
  padding: 40px 0;
  animation: introUp 0.9s cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes introUp { from { opacity: 0; transform: translateY(24px); } }
.brand-top {
  font-size: clamp(13px, 1.6vw, 18px);
  font-weight: 800;
  letter-spacing: 0.62em;
  color: #f4c542;
  margin-bottom: 2px;
}
.brand-main {
  font-family: var(--font-display);
  font-size: clamp(58px, 9vw, 128px);
  line-height: 0.82;
  letter-spacing: -0.02em;
  color: #f7f3e8;
  text-shadow: 0 6px 0 rgba(0, 0, 0, 0.35), 0 20px 60px rgba(0, 0, 0, 0.6);
  transform: skewX(-6deg);
}
.brand-main span {
  display: inline-block;
  color: #ff5b3d;
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.4);
  margin-left: 0.12em;
}
.brand-sub {
  margin-top: 12px;
  font-size: 11px;
  letter-spacing: 0.38em;
  color: rgba(255, 255, 255, 0.55);
}
.intro-copy {
  margin: 26px 0 22px;
  font-size: 15px;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.78);
  border-left: 2px solid rgba(244, 197, 66, 0.65);
  padding-left: 16px;
}
.controls-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px 20px;
  margin: 0 0 26px;
  max-width: 540px;
}
.controls-grid div { display: flex; align-items: center; gap: 9px; font-size: 12px; color: rgba(255, 255, 255, 0.66); }
kbd {
  display: inline-block;
  min-width: 40px;
  padding: 4px 7px;
  text-align: center;
  font-family: var(--font-ui);
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 1px;
  color: #f0ead8;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom: 2px solid rgba(255, 255, 255, 0.12);
  border-radius: 3px;
}
.loading-wrap { max-width: 540px; margin-bottom: 14px; }
.loading-label { display: flex; justify-content: space-between; font-size: 10px; letter-spacing: 2.5px; color: rgba(255, 255, 255, 0.5); margin-bottom: 6px; }
.loading-bar { height: 3px; background: rgba(255, 255, 255, 0.12); overflow: hidden; }
#load-fill { height: 100%; width: 0%; background: linear-gradient(90deg, #f4c542, #ff5b3d); transition: width 0.3s ease; }
.start-btn {
  pointer-events: auto;
  display: inline-block;
  padding: 16px 42px;
  font-family: var(--font-display);
  font-size: 15px;
  letter-spacing: 3px;
  color: #10130f;
  background: linear-gradient(180deg, #d6f5a8, #9be15d);
  border: 0;
  border-radius: 2px;
  cursor: pointer;
  box-shadow: 0 8px 30px rgba(120, 200, 60, 0.28);
  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.2s;
}
.start-btn:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 12px 36px rgba(120, 200, 60, 0.42); }
.start-btn:disabled { opacity: 0.35; cursor: wait; box-shadow: none; }
.ghost-btn {
  pointer-events: auto;
  display: block;
  margin: 12px auto 0;
  padding: 10px 26px;
  font-size: 11px;
  letter-spacing: 2px;
  color: rgba(255, 255, 255, 0.7);
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 2px;
  cursor: pointer;
}
.ghost-btn:hover { color: #fff; border-color: rgba(255, 255, 255, 0.6); }
.intro-foot { display: flex; align-items: center; gap: 10px; margin-top: 26px; font-size: 10.5px; color: rgba(255, 255, 255, 0.4); }
.tag {
  font-family: var(--font-display);
  font-size: 12px;
  padding: 3px 7px;
  color: #0d0f0c;
  background: #cfd3cb;
  border-radius: 2px;
}
.intro-side {
  position: absolute;
  right: 34px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  height: 60vh;
  z-index: 2;
}
.side-line { flex: 1; width: 1px; background: linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.3), transparent); }
.side-text { writing-mode: vertical-rl; font-size: 9px; letter-spacing: 4px; color: rgba(255, 255, 255, 0.42); }

/* ---------------- Pause / Wasted ---------------- */
.pause, .wasted {
  position: absolute; inset: 0; z-index: 70;
  display: flex; align-items: center; justify-content: center;
  background: rgba(4, 6, 7, 0.74);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.pause-panel {
  text-align: center;
  padding: 44px 56px;
  background: rgba(12, 15, 16, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-top: 3px solid var(--gold);
  border-radius: 2px;
  max-width: 460px;
  width: 86vw;
  animation: introUp 0.3s ease;
}
.pause-panel h1 {
  font-family: var(--font-display);
  font-size: 44px; letter-spacing: 5px; margin: 0 0 6px;
}
.pause-panel p { color: rgba(255, 255, 255, 0.55); font-size: 12px; margin: 0 0 24px; letter-spacing: 1px; }
.pause-tip { margin-top: 26px; font-size: 11.5px; line-height: 1.7; color: rgba(255, 255, 255, 0.45); border-top: 1px solid rgba(255, 255, 255, 0.08); padding-top: 16px; }

.wasted { background: #000; }
.wasted-inner { text-align: center; animation: wastedIn 2.4s ease forwards; }
.wasted-title {
  font-family: var(--font-display);
  font-size: clamp(64px, 14vw, 190px);
  letter-spacing: 8px;
  color: #a3201b;
  text-shadow: 0 0 60px rgba(163, 32, 27, 0.35);
  transform: skewX(-5deg);
}
.wasted-sub { font-size: 12px; letter-spacing: 3px; color: rgba(255, 255, 255, 0.55); margin-top: 10px; }
@keyframes wastedIn {
  0% { opacity: 0; transform: scale(1.15); filter: blur(8px); }
  22% { opacity: 1; filter: blur(0); }
  100% { opacity: 1; }
}

/* ---------------- Mobile ---------------- */
.mobile-controls { position: absolute; inset: 0; pointer-events: none; }
.stick-zone {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  bottom: calc(max(22px, env(safe-area-inset-bottom)) + 240px);
  width: 132px; height: 132px;
  pointer-events: auto;
  touch-action: none;
}
.stick-base {
  position: absolute; inset: 0; border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.25);
  background: radial-gradient(circle, rgba(255, 255, 255, 0.08), rgba(0, 0, 0, 0.25));
}
.stick-knob {
  position: absolute; left: 50%; top: 50%; width: 54px; height: 54px;
  margin: -27px 0 0 -27px; border-radius: 50%;
  background: rgba(255, 255, 255, 0.22);
  border: 1.5px solid rgba(255, 255, 255, 0.5);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);
}
.look-zone { position: absolute; right: 0; top: 0; width: 55%; height: 75%; pointer-events: auto; touch-action: none; }
.touch-buttons {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(3, 56px);
  gap: 9px;
  pointer-events: none;
}
.tbtn {
  pointer-events: auto;
  width: 56px; height: 56px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.35);
  background: rgba(10, 12, 14, 0.5);
  color: rgba(255, 255, 255, 0.85);
  font-size: 10px; font-weight: 800; letter-spacing: 0.5px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  touch-action: none;
}
.tbtn:active { background: rgba(255, 255, 255, 0.3); }
.tbtn.fire {
  width: 72px; height: 72px;
  border-color: rgba(255, 110, 90, 0.6);
  background: rgba(180, 40, 30, 0.4);
  font-size: 11px;
}
.tbtn.small { width: 52px; height: 52px; align-self: center; }
