import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const CAR_COLORS = [0xb6312a, 0x2b5d9e, 0xe8e6df, 0x16181c, 0x9aa0a6, 0xd97a24, 0x3d6b45, 0xc9b23a, 0x4a2f63, 0x2d7a78, 0x77242b, 0x53616b];

const TYPES = {
  sedan: { len: 4.5, width: 1.88, height: 1.42, maxSpeed: 27, accel: 11, turn: 2.1, name: 'Sultan' },
  sports: { len: 4.55, width: 1.98, height: 1.14, maxSpeed: 38, accel: 17, turn: 2.25, name: 'Banshee' },
  suv: { len: 4.95, width: 2.02, height: 1.76, maxSpeed: 24, accel: 9.5, turn: 1.8, name: 'Rancher' },
  taxi: { len: 4.6, width: 1.9, height: 1.52, maxSpeed: 25, accel: 10.5, turn: 2.0, name: 'Downtown Cab' },
  van: { len: 5.3, width: 2.08, height: 1.92, maxSpeed: 21, accel: 8, turn: 1.7, name: 'Speedo' },
  police: { len: 4.7, width: 1.98, height: 1.55, maxSpeed: 33, accel: 14, turn: 2.15, name: 'LSPD Cruiser' },
};

const bodyCache = new Map();
const lightCache = new Map();
const wheelCache = new Map();
const lightMat = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false });
const wheelMat = new THREE.MeshStandardMaterial({ color: 0x141517, roughness: 0.9 });
const glassMat = new THREE.MeshStandardMaterial({ color: 0x26333d, roughness: 0.15, metalness: 0.7 });

function coloredBox(geos, w, h, d, color, x, y, z) {
  const g = new THREE.BoxGeometry(w, h, d);
  const c = new THREE.Color(color);
  const n = g.attributes.position.count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    arr[i * 3] = c.r;
    arr[i * 3 + 1] = c.g;
    arr[i * 3 + 2] = c.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  g.translate(x, y, z);
  geos.push(g);
}

function buildBody(type, color, isPolice, isTaxi) {
  const key = `${type}|${color}|${isPolice ? 1 : 0}|${isTaxi ? 1 : 0}`;
  if (bodyCache.has(key)) return bodyCache.get(key);
  const t = TYPES[type];
  const { len, width, height } = t;
  const body = [];
  const lights = [];
  const bodyColor = isPolice ? 0xe8e8e7 : isTaxi ? 0xd8b32c : color;
  const lowerH = height * 0.4;
  const baseY = 0.33;

  // main hull
  coloredBox(body, width, lowerH, len, bodyColor, 0, baseY + lowerH / 2, 0);
  // hood and trunk
  const deckY = baseY + lowerH + 0.04;
  coloredBox(body, width * 0.96, 0.12, len * 0.27, bodyColor, 0, deckY + 0.06, len * 0.31);
  coloredBox(body, width * 0.96, 0.12, len * 0.24, bodyColor, 0, deckY + 0.06, -len * 0.33);
  // cabin
  const cabinH = height * (type === 'sports' ? 0.32 : 0.4);
  const cabinLen = len * (type === 'van' ? 0.62 : 0.44);
  const cabinZ = type === 'van' ? -len * 0.13 : -len * 0.06;
  coloredBox(body, width * 0.86, cabinH, cabinLen, glassMat.color, 0, deckY + cabinH / 2, cabinZ);
  // roof
  coloredBox(body, width * 0.8, 0.09, cabinLen * 0.86, bodyColor, 0, deckY + cabinH + 0.045, cabinZ);
  // pillars
  coloredBox(body, width * 0.88, 0.11, 0.1, bodyColor, 0, deckY + cabinH * 0.6, cabinZ + cabinLen * 0.42);
  coloredBox(body, width * 0.88, 0.11, 0.1, bodyColor, 0, deckY + cabinH * 0.6, cabinZ - cabinLen * 0.42);
  // bumpers
  coloredBox(body, width * 0.94, 0.18, 0.22, 0x1b1d20, 0, baseY + 0.12, len / 2 - 0.02);
  coloredBox(body, width * 0.94, 0.18, 0.22, 0x1b1d20, 0, baseY + 0.12, -len / 2 + 0.02);
  // side skirts
  coloredBox(body, width + 0.02, 0.1, len * 0.62, 0x22252a, 0, baseY + 0.06, 0);

  if (isPolice) {
    coloredBox(body, width + 0.03, 0.28, len * 0.55, 0x141619, 0, baseY + lowerH * 0.62, -len * 0.03);
  }
  if (isTaxi) {
    coloredBox(body, 0.62, 0.16, 0.32, 0xe8e2c8, 0, deckY + cabinH + 0.18, cabinZ + 0.1);
  }

  // headlights & taillights
  const headY = baseY + lowerH * 0.62;
  const hx = width * 0.32;
  const lightCol = 0xfff0c0;
  const tailCol = 0xff2f24;
  for (const sx of [-1, 1]) {
    coloredBox(lights, width * 0.2, 0.14, 0.06, lightCol, sx * hx, headY, len / 2 - 0.01);
    coloredBox(lights, width * 0.18, 0.12, 0.05, tailCol, sx * hx, headY, -len / 2 + 0.01);
  }

  const merged = mergeGeometries(body);
  const lightsGeo = mergeGeometries(lights);
  const out = { body: merged, lights: lightsGeo };
  bodyCache.set(key, out);

  if (!wheelCache.has(type)) {
    const wheels = [];
    const wr = 0.34;
    const wz = len * 0.31;
    const wx = width / 2 - 0.06;
    for (const sx of [-1, 1]) {
      for (const sz of [-1, 1]) {
        const cyl = new THREE.CylinderGeometry(wr, wr, 0.26, 10);
        cyl.rotateZ(Math.PI / 2);
        cyl.translate(sx * wx, wr, sz * wz);
        wheels.push(cyl);
      }
    }
    wheelCache.set(type, mergeGeometries(wheels));
  }
  return out;
}

function makePoliceDecalTexture() {
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 64;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 256, 64);
  ctx.fillStyle = 'rgba(12,16,24,0.85)';
  ctx.fillRect(0, 0, 256, 64);
  ctx.fillStyle = '#e8eef5';
  ctx.font = '900 34px "Arial Black", Impact, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('POLICE', 128, 34);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}
let policeDecalTex = null;

export class Vehicle {
  constructor(scene, opts = {}) {
    const type = opts.type || 'sedan';
    const t = TYPES[type];
    this.scene = scene;
    this.type = type;
    this.stats = t;
    this.name = t.name;
    this.isPolice = !!opts.isPolice || type === 'police';
    this.isTaxi = type === 'taxi';
    this.color = opts.color ?? (this.isPolice ? 0xe8e8e7 : this.isTaxi ? 0xd8b32c : pick(CAR_COLORS));
    this.heading = opts.heading ?? 0;
    this.speed = opts.speed ?? 0;
    this.steer = 0;
    this.throttle = 0;
    this.brake = 0;
    this.health = 100;
    this.dead = false;
    this.isPlayer = false;
    this.ai = null;
    this.group = new THREE.Group();
    this.group.position.set(opts.x ?? 0, 0, opts.z ?? 0);
    this.group.rotation.y = this.heading;
    this.scene.add(this.group);

    const built = buildBody(type, this.color, this.isPolice, this.isTaxi);
    this.bodyMesh = new THREE.Mesh(built.body, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.38, metalness: 0.45 }));
    this.bodyMesh.castShadow = true;
    this.bodyMesh.receiveShadow = true;
    this.group.add(this.bodyMesh);

    this.lightsMesh = new THREE.Mesh(built.lights, lightMat);
    this.group.add(this.lightsMesh);

    this.wheelsMesh = new THREE.Mesh(wheelCache.get(type), wheelMat);
    this.wheelsMesh.castShadow = true;
    this.group.add(this.wheelsMesh);

    if (this.isPolice) {
      this.redLight = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.14, 0.3), new THREE.MeshBasicMaterial({ color: 0xff2a24, toneMapped: false }));
      this.blueLight = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.14, 0.3), new THREE.MeshBasicMaterial({ color: 0x2f7dff, toneMapped: false }));
      this.redLight.position.set(-0.52, 1.62, -0.1);
      this.blueLight.position.set(0.52, 1.62, -0.1);
      this.group.add(this.redLight, this.blueLight);
      const bar = new THREE.Mesh(new THREE.BoxGeometry(1.25, 0.1, 0.36), new THREE.MeshStandardMaterial({ color: 0x1a1c1f }));
      bar.position.set(0, 1.55, -0.1);
      this.group.add(bar);

      if (!policeDecalTex) policeDecalTex = makePoliceDecalTexture();
      const decalMat = new THREE.MeshBasicMaterial({ map: policeDecalTex, transparent: true, depthWrite: false });
      for (const sx of [-1, 1]) {
        const d = new THREE.Mesh(new THREE.PlaneGeometry(2.5, 0.62), decalMat);
        d.position.set(sx * (t.width / 2 + 0.012), 0.66, -0.15);
        d.rotation.y = sx * Math.PI / 2;
        this.group.add(d);
      }
    }

    this.radius = t.width * 0.52;
    this.smokeTimer = 0;
    this.fireTimer = 0;
    this.flashTimer = 0;
    this.collisionCooldown = 0;
    this.entered = false;
  }

  get pos() { return this.group.position; }

  enter(player) {
    this.isPlayer = true;
    this.ai = null;
    this.entered = true;
    this.throttle = 0;
  }

  exit() {
    this.isPlayer = false;
    this.throttle = 0;
    this.brake = 1;
  }

  damage(amount, game, source = 'bullet') {
    if (this.dead) return;
    this.health -= amount;
    if (this.health <= 0) {
      this.health = 0;
      this.dead = true;
      this.speed *= 0.3;
      game.vehicles.explode(this, game);
    }
  }

  updatePhysics(dt, game) {
    this.collisionCooldown = Math.max(0, this.collisionCooldown - dt);
    if (this.dead) {
      this.speed *= Math.max(0, 1 - dt * 4);
      this._integrate(dt, game, true);
      return;
    }

    if (this.isPlayer) {
      const input = game.input;
      const forward = this.speed;
      this.throttle = input.forward ? 1 : 0;
      if (input.back) this.throttle = forward > 0.6 ? 0 : -0.65;
      if (input.back && forward > 0.6) this.brake = 1;
      else this.brake = input.brake ? 1 : 0;
      this.steer = input.left ? -1 : input.right ? 1 : 0;
      if (input.brake && Math.abs(this.speed) > 6) this.steer *= 1.5;
    } else if (this.ai) {
      this._updateAI(dt, game);
    } else {
      this.throttle = 0;
      this.steer = 0;
      this.brake = 0.35;
    }

    // engine / brake
    if (this.throttle > 0) {
      this.speed += this.stats.accel * this.throttle * dt;
    } else if (this.throttle < 0) {
      if (this.speed > 0.4) this.speed += this.throttle * this.stats.accel * 1.8 * dt;
      else this.speed += this.throttle * this.stats.accel * 0.5 * dt;
    }
    if (this.brake) {
      const dec = 24 * this.brake * dt;
      if (this.speed > 0) this.speed = Math.max(0, this.speed - dec);
      else this.speed = Math.min(0, this.speed + dec);
    }
    // drag + rolling resistance
    this.speed -= this.speed * (0.18 + (this.isPlayer ? 0 : 0.12)) * dt;
    if (!this.throttle && !this.brake) {
      const roll = 1.2 * dt;
      if (this.speed > 0) this.speed = Math.max(0, this.speed - roll);
      else this.speed = Math.min(0, this.speed + roll);
    }
    this.speed = clamp(this.speed, -this.stats.maxSpeed * 0.34, this.stats.maxSpeed);

    const steerFactor = clamp(Math.abs(this.speed) / 7, 0, 1) * (1 - clamp(Math.abs(this.speed) / (this.stats.maxSpeed * 2.6), 0, 0.35));
    this.heading += this.steer * this.stats.turn * steerFactor * dt * Math.sign(this.speed || 1);
    this._integrate(dt, game, false);

    if (this.isPlayer) {
      const a = game.audio;
      if (a) a.updateEngine(Math.abs(this.speed) / this.stats.maxSpeed, this.throttle);
    }

    // damage smoke
    if (this.health < 42) {
      this.smokeTimer -= dt;
      if (this.smokeTimer <= 0) {
        this.smokeTimer = 0.16;
        const f = new THREE.Vector3(Math.sin(this.heading), 0, Math.cos(this.heading));
        const p = this.pos.clone().addScaledVector(f, this.stats.len * 0.34);
        p.y = 0.9;
        game.fx.burst(p, { count: 2, color: 0x444444, speed: 1.2, life: 1.3, size: 0.7, gravity: -0.5, kind: 'smoke' });
      }
    }
  }

  _integrate(dt, game, dead) {
    if (Math.abs(this.speed) < 0.01 && dead) return;
    const fx = Math.sin(this.heading) * this.speed * dt;
    const fz = Math.cos(this.heading) * this.speed * dt;
    let nx = this.pos.x + fx;
    let nz = this.pos.z + fz;
    const res = game.world.resolveCircle(nx, nz, 1.15);
    if (res.hit) {
      const impactSpeed = Math.abs(this.speed);
      this.speed *= -0.22;
      if (impactSpeed > 4 && this.collisionCooldown <= 0) {
        this.collisionCooldown = 0.22;
        this.health -= impactSpeed * 0.85;
        const p = this.pos.clone();
        p.y = 0.55;
        game.fx.sparks(p, null);
        if (this.isPlayer) {
          game.fx.shake = Math.max(game.fx.shake, Math.min(0.5, impactSpeed * 0.02));
          game.audio.crash(impactSpeed);
        }
        if (this.health <= 0 && !this.dead) {
          this.dead = true;
          game.vehicles.explode(this, game);
        }
      }
    }
    nx = res.x;
    nz = res.z;
    this.group.position.x = nx;
    this.group.position.z = nz;
    this.group.rotation.y = this.heading;

    if (this.isPolice) {
      this.flashTimer += dt;
      const on = Math.sin(this.flashTimer * 14) > 0;
      if (this.redLight) this.redLight.visible = on;
      if (this.blueLight) this.blueLight.visible = !on;
    }
  }

  _updateAI(dt, game) {
    const ai = this.ai;
    const target = ai.target;
    if (!target) return;
    const tp = target.vehicle ? target.vehicle.pos : target.pos;
    if (!tp) return;
    let tx = tp.x;
    let tz = tp.z;

    if (ai.type === 'traffic') {
      if (ai.waypoint) {
        tx = ai.waypoint.x;
        tz = ai.waypoint.z;
        const d = Math.hypot(tx - this.pos.x, tz - this.pos.z);
        if (d < 5.5) {
          this._nextTrafficWaypoint(game.world);
          tx = ai.waypoint.x;
          tz = ai.waypoint.z;
        }
      }
    }

    const dx = tx - this.pos.x;
    const dz = tz - this.pos.z;
    const dist = Math.hypot(dx, dz);
    const desired = Math.atan2(dx, dz);
    let diff = ((desired - this.heading + Math.PI) % (Math.PI * 2)) - Math.PI;
    if (diff < -Math.PI) diff += Math.PI * 2;
    this.steer = clamp(diff * 2.4, -1, 1);

    let desiredSpeed = this.stats.maxSpeed * (ai.type === 'chase' ? 0.95 : 0.46);
    if (Math.abs(diff) > 0.8) desiredSpeed *= 0.4;
    if (dist < 16 && ai.type === 'chase') desiredSpeed = Math.max(0, (dist - 6) * 1.6);

    // obstacle avoidance
    let blocked = false;
    const fwdX = Math.sin(this.heading);
    const fwdZ = Math.cos(this.heading);
    for (const other of game.vehicles.vehicles) {
      if (other === this) continue;
      const ox = other.pos.x - this.pos.x;
      const oz = other.pos.z - this.pos.z;
      const ahead = ox * fwdX + oz * fwdZ;
      const lateral = Math.abs(ox * fwdZ - oz * fwdX);
      if (ahead > 1 && ahead < 10 && lateral < 2.3) {
        blocked = true;
        break;
      }
    }
    const player = game.player;
    if (!player.vehicle) {
      const ox = player.pos.x - this.pos.x;
      const oz = player.pos.z - this.pos.z;
      const ahead = ox * fwdX + oz * fwdZ;
      const lateral = Math.abs(ox * fwdZ - oz * fwdX);
      if (ahead > 0 && ahead < 8 && lateral < 2.2) blocked = true;
    }
    if (blocked) desiredSpeed = 0;

    if (this.speed < desiredSpeed - 0.4) this.throttle = 0.8;
    else if (this.speed > desiredSpeed + 1.2) this.throttle = -0.3;
    else this.throttle = 0.05;
    this.brake = desiredSpeed === 0 && this.speed > 0.4 ? 1 : 0;
    if (this.brake) this.throttle = 0;
  }

  initTraffic(world) {
    this.ai = { type: 'traffic', waypoint: null };
    this.nodeI = clamp(Math.round(this.pos.x / 78), -4, 4);
    this.nodeJ = clamp(Math.round(this.pos.z / 78), -4, 4);
    // determine closest direction from heading
    const s = Math.sin(this.heading);
    const c = Math.cos(this.heading);
    if (Math.abs(s) > Math.abs(c)) this.dir = s > 0 ? 0 : 2;
    else this.dir = c > 0 ? 1 : 3;
    this._nextTrafficWaypoint(world);
  }

  _nextTrafficWaypoint(world) {
    const dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]];
    const reverse = (this.dir + 2) % 4;
    const options = [];
    for (let d = 0; d < 4; d++) {
      if (d === reverse) continue;
      const ni = this.nodeI + dirs[d][0];
      const nj = this.nodeJ + dirs[d][1];
      if (ni < -4 || ni > 4 || nj < -4 || nj > 4) continue;
      const weight = d === this.dir ? 0.55 : 0.225;
      options.push({ d, ni, nj, weight });
    }
    if (!options.length) {
      this.nodeI = clamp(this.nodeI + dirs[reverse][0], -4, 4);
      this.nodeJ = clamp(this.nodeJ + dirs[reverse][1], -4, 4);
      this.dir = reverse;
    } else {
      let r = Math.random();
      let chosen = options[0];
      for (const o of options) {
        r -= o.weight;
        if (r <= 0) { chosen = o; break; }
      }
      this.nodeI = chosen.ni;
      this.nodeJ = chosen.nj;
      this.dir = chosen.d;
    }
    const offset = 3.4;
    let x = this.nodeI * 78;
    let z = this.nodeJ * 78;
    if (this.dir === 0) z += offset;
    if (this.dir === 2) z -= offset;
    if (this.dir === 1) x -= offset;
    if (this.dir === 3) x += offset;
    this.ai.waypoint = { x, z };
  }
}

export class VehicleManager {
  constructor(scene, world) {
    this.scene = scene;
    this.world = world;
    this.vehicles = [];
    this.trafficCount = 15;
    this.headlight = new THREE.SpotLight(0xfff0c8, 0, 62, 0.55, 0.5, 1.2);
    this.headlight.castShadow = false;
    this.headlight.position.set(0, 1, 0);
    this.scene.add(this.headlight);
    this.headlight.target = new THREE.Object3D();
    this.scene.add(this.headlight.target);
    this._spawnParked();
    this._spawnTraffic();
  }

  add(opts) {
    const v = new Vehicle(this.scene, opts);
    this.vehicles.push(v);
    return v;
  }

  _roadSpawn(minDist, maxDist, from) {
    for (let tries = 0; tries < 60; tries++) {
      const alongZ = Math.random() < 0.5;
      const line = Math.floor(rand(-4, 5));
      const t = rand(-3.8, 3.8) * 78;
      const dir = Math.random() < 0.5 ? 1 : -1;
      let x;
      let z;
      let heading;
      if (alongZ) {
        x = line * 78 + (dir > 0 ? -3.4 : 3.4);
        z = t;
        heading = dir > 0 ? 0 : Math.PI;
      } else {
        x = t;
        z = line * 78 + (dir > 0 ? 3.4 : -3.4);
        heading = dir > 0 ? Math.PI / 2 : -Math.PI / 2;
      }
      if (from && (Math.hypot(x - from.x, z - from.z) < minDist || Math.hypot(x - from.x, z - from.z) > maxDist)) continue;
      if (this.world.isBlocked(x, z, 1.5)) continue;
      return { x, z, heading };
    }
    return { x: 0, z: 40, heading: 0 };
  }

  _spawnTraffic() {
    for (let i = 0; i < this.trafficCount; i++) {
      const spot = this._roadSpawn(20, 260, { x: 0, z: 0 });
      const v = this.add({
        x: spot.x, z: spot.z, heading: spot.heading,
        type: pick(['sedan', 'sedan', 'suv', 'sports', 'van', 'taxi']),
        speed: rand(3, 9),
      });
      v.initTraffic(this.world);
    }
  }

  _spawnParked() {
    // roadside parked cars
    const used = new Set();
    for (let i = 0; i < 26; i++) {
      const block = pick(this.world.blocks);
      if (block.isPark) continue;
      const key = `${block.i},${block.j}`;
      if (used.has(key)) continue;
      used.add(key);
      const side = Math.floor(Math.random() * 4);
      const t = rand(8, 56);
      let x;
      let z;
      let heading;
      if (side === 0) { x = block.x0 - 2.0; z = block.z0 + t; heading = 0; }
      if (side === 1) { x = block.x1 + 2.0; z = block.z0 + t; heading = Math.PI; }
      if (side === 2) { x = block.x0 + t; z = block.z0 - 2.0; heading = Math.PI / 2; }
      if (side === 3) { x = block.x0 + t; z = block.z1 + 2.0; heading = -Math.PI / 2; }
      if (this.world.isBlocked(x, z, 1.2)) continue;
      this.add({ x, z, heading, type: pick(['sedan', 'sports', 'suv', 'taxi', 'van', 'sedan']), color: pick(CAR_COLORS) });
    }
    // parking lots
    let lots = 0;
    for (const block of this.world.parkingBlocks) {
      if (lots > 3) break;
      lots++;
      for (const spot of block.parkingSpots || []) {
        if (Math.random() < 0.6) {
          this.add({ x: spot.x, z: spot.z, heading: spot.heading, type: pick(['sedan', 'suv', 'sports']) });
        }
      }
    }
    // a guaranteed ride near the player spawn
    this.add({ x: 156 + 6.2, z: 172.5, heading: Math.PI, type: 'sedan', color: 0x2b5d9e });
    this.add({ x: 156 - 5.8, z: 150, heading: 0, type: 'taxi' });
  }

  nearest(pos, maxDist) {
    let best = null;
    let bestD = maxDist;
    for (const v of this.vehicles) {
      if (v.dead) continue;
      const d = Math.hypot(v.pos.x - pos.x, v.pos.z - pos.z);
      if (d < bestD) { bestD = d; best = v; }
    }
    return best;
  }

  spawnTrafficNear(pos) {
    const spot = this._roadSpawn(80, 240, pos);
    const v = this.add({
      x: spot.x, z: spot.z, heading: spot.heading,
      type: pick(['sedan', 'sedan', 'suv', 'sports', 'van', 'taxi']),
      speed: rand(4, 8),
    });
    v.initTraffic(this.world);
    return v;
  }

  update(dt, game) {
    const player = game.player;
    for (const v of this.vehicles) {
      v.updatePhysics(dt, game);
      if (!v.isPlayer && v.ai?.type === 'traffic') {
        const d = Math.hypot(v.pos.x - player.pos.x, v.pos.z - player.pos.z);
        if (d > 290) {
          // recycle far traffic
          const spot = this._roadSpawn(100, 240, player.pos);
          v.group.position.set(spot.x, 0, spot.z);
          v.heading = spot.heading;
          v.group.rotation.y = spot.heading;
          v.speed = rand(3, 8);
          v.initTraffic(this.world);
        }
      }
    }

    // car vs car
    for (let i = 0; i < this.vehicles.length; i++) {
      const a = this.vehicles[i];
      if (a.dead) continue;
      for (let j = i + 1; j < this.vehicles.length; j++) {
        const b = this.vehicles[j];
        if (b.dead) continue;
        const dx = b.pos.x - a.pos.x;
        const dz = b.pos.z - a.pos.z;
        const minD = 2.35;
        const d2 = dx * dx + dz * dz;
        if (d2 > minD * minD || d2 < 1e-5) continue;
        const d = Math.sqrt(d2);
        const push = (minD - d) * 0.5;
        const nx = dx / d;
        const nz = dz / d;
        a.pos.x -= nx * push;
        a.pos.z -= nz * push;
        b.pos.x += nx * push;
        b.pos.z += nz * push;
        const rel = Math.abs(a.speed - b.speed);
        if (rel > 5) {
          a.health -= rel * 0.4;
          b.health -= rel * 0.4;
          if (a.isPlayer || b.isPlayer) {
            game.audio.crash(rel);
            game.fx.shake = Math.max(game.fx.shake, 0.2);
          }
        }
        a.speed *= 0.92;
        b.speed *= 0.92;
        if (a.health <= 0 && !a.dead) { a.dead = true; this.explode(a, game); }
        if (b.health <= 0 && !b.dead) { b.dead = true; this.explode(b, game); }
      }
    }

    // run over characters
    if (!game.player.isDead) {
      for (const v of this.vehicles) {
        if (v.dead || Math.abs(v.speed) < 5) continue;
        const fx = Math.sin(v.heading);
        const fz = Math.cos(v.heading);
        const frontX = v.pos.x + fx * v.stats.len * 0.42;
        const frontZ = v.pos.z + fz * v.stats.len * 0.42;
        const targets = [game.peds, game.enemies];
        for (const arr of targets) {
          for (const c of arr) {
            if (!c.alive) continue;
            if (Math.hypot(c.pos.x - frontX, c.pos.z - frontZ) < 1.35) {
              const wasPlayer = v.isPlayer;
              c.damage(999, game, { car: true });
              if (wasPlayer && c.kind !== 'cop' && c.kind !== 'gangster') {
                game.addWanted(1, '보행자를 치었습니다');
              }
              if (wasPlayer && game.audio) game.audio.thud(c.pos);
            }
          }
        }
      }
    }

    // headlights for player car
    const pv = player.vehicle;
    if (pv && !pv.dead) {
      const fx = Math.sin(pv.heading);
      const fz = Math.cos(pv.heading);
      const rightX = Math.cos(pv.heading);
      const rightZ = -Math.sin(pv.heading);
      this.headlight.position.set(pv.pos.x + fx * pv.stats.len * 0.45, 1.0, pv.pos.z + fz * pv.stats.len * 0.45);
      this.headlight.target.position.set(pv.pos.x + fx * 30, 0.1, pv.pos.z + fz * 30);
      this.headlight.intensity = game.world.night * 55;
    } else {
      this.headlight.intensity = 0;
    }
  }

  explode(v, game) {
    if (v.exploded) return;
    v.exploded = true;
    v.dead = true;
    game.fx.explosion(v.pos.clone());
    game.audio.explosion(v.pos);
    if (v.isPlayer && game.player.vehicle === v) {
      game.player.vehicle = null;
      game.player.group.visible = true;
      game.player.group.position.set(v.pos.x, 1.2, v.pos.z);
      game.player.damage(220, game, { explosion: true });
    }
    // blast damage
    for (const c of [...game.peds, ...game.enemies]) {
      if (c.alive && c.pos.distanceTo(v.pos) < 7) c.damage(180, game, { explosion: true });
    }
    if (game.player.alive && !game.player.vehicle && game.player.pos.distanceTo(v.pos) < 6) {
      game.player.damage(80, game, { explosion: true });
    }
    game.addWanted(1, '차량 폭발');
    if (v.ai) v.ai = null;
    v.bodyMesh.material.color.setHex(0x2a2724);
  }
}

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

export class Input {
  constructor(game) {
    this.game = game;
    this.keys = new Set();
    this.moveX = 0;
    this.moveY = 0;
    this.mouseDown = false;
    this.aim = false;
    this.jump = false;
    this.sprint = false;
    this.brake = false;
    this.lookX = 0;
    this.lookY = 0;
    this.locked = false;
    this.touch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.touchAimToggle = false;
    this.touchFire = false;
    this.touchSprint = false;
    this.touchBrake = false;
    this.stickPointer = null;
    this.stickCenter = { x: 0, y: 0 };
    this.lookPointer = null;
    this.lastLook = { x: 0, y: 0 };
    this.sensitivity = this.touch ? 0.0045 : 0.0022;
    this._bindKeyboard();
    this._bindMouse();
    this._bindTouch();
  }

  get forward() { return this.moveY > 0.15; }
  get back() { return this.moveY < -0.15; }
  get left() { return this.moveX < -0.15; }
  get right() { return this.moveX > 0.15; }
  get firing() { return this.mouseDown || this.touchFire; }
  get aiming() { return this.aim || (this.touchAimToggle && !this.game.player?.inVehicle); }

  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(e.code)) e.preventDefault();
      if (e.repeat) {
        this.keys.add(e.code);
        return;
      }
      this.keys.add(e.code);
      const game = this.game;
      if (!game || game.state !== 'playing') return;
      switch (e.code) {
        case 'KeyF':
        case 'KeyE':
          if (game.player.inVehicle) game.player.exitVehicle(game);
          else game.player.tryEnterVehicle(game, true);
          break;
        case 'KeyR':
          game.player.reload(game);
          break;
        case 'Digit1':
          game.player.switchWeapon(0, game);
          break;
        case 'Digit2':
          game.player.switchWeapon(1, game);
          break;
        case 'Digit3':
          game.player.switchWeapon(2, game);
          break;
        case 'KeyH':
          if (game.player.inVehicle) game.audio.horn();
          break;
        case 'KeyB':
          if (game.player.inVehicle && game.radio) game.radio.next();
          break;
        case 'Space':
          this.jump = true;
          break;
        case 'Escape':
          if (!this.touch && this.locked) document.exitPointerLock();
          else game.pause();
          break;
        default:
          break;
      }
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.mouseDown = false;
      this.aim = false;
    });
  }

  _bindMouse() {
    const canvas = this.game.canvas;
    canvas.addEventListener('mousedown', (e) => {
      if (this.game.state !== 'playing') return;
      if (!this.touch && !this.locked) {
        canvas.requestPointerLock?.();
        return;
      }
      if (e.button === 0) this.mouseDown = true;
      if (e.button === 2) this.aim = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.mouseDown = false;
      if (e.button === 2) this.aim = false;
    });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    document.addEventListener('pointerlockchange', () => {
      this.locked = document.pointerLockElement === canvas;
      if (!this.locked && this.game.state === 'playing' && !this.touch) this.game.pause();
    });
    document.addEventListener('mousemove', (e) => {
      if (!this.locked) return;
      this.lookX += e.movementX;
      this.lookY += e.movementY;
    });
  }

  _bindTouch() {
    if (!this.touch) return;
    const stickZone = document.getElementById('stick-zone');
    const knob = document.getElementById('stick-knob');
    const lookZone = document.getElementById('look-zone');

    if (stickZone) {
      const resetStick = () => {
        this.stickPointer = null;
        this.moveX = 0;
        this.moveY = 0;
        if (knob) knob.style.transform = 'translate(0px, 0px)';
      };
      stickZone.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.stickPointer = e.pointerId;
        const r = stickZone.getBoundingClientRect();
        this.stickCenter = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
        stickZone.setPointerCapture(e.pointerId);
        this._moveStick(e.clientX, e.clientY, knob);
      });
      stickZone.addEventListener('pointermove', (e) => {
        if (e.pointerId !== this.stickPointer) return;
        this._moveStick(e.clientX, e.clientY, knob);
      });
      stickZone.addEventListener('pointerup', (e) => { if (e.pointerId === this.stickPointer) resetStick(); });
      stickZone.addEventListener('pointercancel', (e) => { if (e.pointerId === this.stickPointer) resetStick(); });
    }

    if (lookZone) {
      lookZone.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.lookPointer = e.pointerId;
        this.lastLook = { x: e.clientX, y: e.clientY };
        lookZone.setPointerCapture(e.pointerId);
      });
      lookZone.addEventListener('pointermove', (e) => {
        if (e.pointerId !== this.lookPointer) return;
        const dx = e.clientX - this.lastLook.x;
        const dy = e.clientY - this.lastLook.y;
        this.lastLook = { x: e.clientX, y: e.clientY };
        this.lookX += dx * 1.1;
        this.lookY += dy * 1.1;
      });
      const end = (e) => { if (e.pointerId === this.lookPointer) this.lookPointer = null; };
      lookZone.addEventListener('pointerup', end);
      lookZone.addEventListener('pointercancel', end);
    }

    const hold = (id, on, off) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); on(); el.setPointerCapture(e.pointerId); });
      el.addEventListener('pointerup', (e) => { e.preventDefault(); off(); });
      el.addEventListener('pointercancel', () => off());
    };
    hold('btn-fire', () => { this.touchFire = true; }, () => { this.touchFire = false; });
    hold('btn-sprint', () => { this.touchSprint = true; this.sprint = true; }, () => { this.touchSprint = false; this.sprint = false; });
    hold('btn-brake', () => { this.touchBrake = true; }, () => { this.touchBrake = false; });
    hold('btn-aim', () => { this.touchAimToggle = !this.touchAimToggle; }, () => {});

    const tap = (id, fn) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); fn(); });
    };
    tap('btn-jump', () => { this.jump = true; });
    tap('btn-enter', () => {
      if (this.game.player.inVehicle) this.game.player.exitVehicle(this.game);
      else this.game.player.tryEnterVehicle(this.game, true);
    });
    tap('btn-reload', () => this.game.player.reload(this.game));
  }

  _moveStick(x, y, knob) {
    const dx = x - this.stickCenter.x;
    const dy = y - this.stickCenter.y;
    const max = 48;
    const len = Math.hypot(dx, dy);
    const k = len > max ? max / len : 1;
    const nx = dx * k;
    const ny = dy * k;
    this.moveX = clamp(nx / max, -1, 1);
    this.moveY = clamp(-ny / max, -1, 1);
    if (knob) knob.style.transform = `translate(${nx}px, ${ny}px)`;
  }

  update() {
    if (this.touch) {
      // touch axes already set by the stick
      this.moveX = clamp(this.moveX, -1, 1);
      this.moveY = clamp(this.moveY, -1, 1);
      this.sprint = this.touchSprint;
      this.brake = this.touchBrake;
    } else {
      this.moveX = (this.keys.has('KeyD') || this.keys.has('ArrowRight') ? 1 : 0) - (this.keys.has('KeyA') || this.keys.has('ArrowLeft') ? 1 : 0);
      this.moveY = (this.keys.has('KeyW') || this.keys.has('ArrowUp') ? 1 : 0) - (this.keys.has('KeyS') || this.keys.has('ArrowDown') ? 1 : 0);
      this.sprint = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
      this.aim = this.aim || this.keys.has('ShiftRight') && false;
      this.brake = this.keys.has('Space');
    }
  }

  consumeLook() {
    const out = { x: this.lookX, y: this.lookY };
    this.lookX = 0;
    this.lookY = 0;
    return out;
  }

  postUpdate() {
    this.jump = false;
  }
}

import * as THREE from 'three';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const tmp = new THREE.Vector3();
const tmp2 = new THREE.Vector3();

function raySphere(origin, dir, center, radius, maxDist) {
  const ox = center.x - origin.x;
  const oy = center.y - origin.y;
  const oz = center.z - origin.z;
  const tca = ox * dir.x + oy * dir.y + oz * dir.z;
  if (tca < 0) return null;
  const d2 = ox * ox + oy * oy + oz * oz - tca * tca;
  const r2 = radius * radius;
  if (d2 > r2) return null;
  const thc = Math.sqrt(r2 - d2);
  const t = tca - thc;
  if (t < 0 || t > maxDist) return null;
  return t;
}

function rayBox(origin, dir, min, max, maxDist) {
  let tmin = 0;
  let tmax = maxDist;
  for (const axis of ['x', 'y', 'z']) {
    const o = origin[axis];
    const d = dir[axis];
    if (Math.abs(d) < 1e-8) {
      if (o < min[axis] || o > max[axis]) return null;
    } else {
      let t1 = (min[axis] - o) / d;
      let t2 = (max[axis] - o) / d;
      if (t1 > t2) { const tt = t1; t1 = t2; t2 = tt; }
      tmin = Math.max(tmin, t1);
      tmax = Math.min(tmax, t2);
      if (tmin > tmax) return null;
    }
  }
  if (tmax < 0) return null;
  return tmin >= 0 ? tmin : tmax;
}

export class Combat {
  constructor(game) {
    this.game = game;
    this.lastHit = 0;
    this.shots = 0;
  }

  getAimDir(origin, dir) {
    const game = this.game;
    const targets = [...game.enemies, ...game.peds.filter((p) => p.alive && p.fleeTimer > 0)];
    let best = null;
    let bestScore = 0.34;
    for (const c of targets) {
      if (!c.alive) continue;
      const dx = c.pos.x - origin.x;
      const dz = c.pos.z - origin.z;
      const dy = 1.1 - origin.y;
      const len = Math.hypot(dx, dy, dz);
      if (len > 60) continue;
      const dot = (dx * dir.x + dy * dir.y + dz * dir.z) / len;
      const angle = Math.acos(clamp(dot, -1, 1));
      if (angle < bestScore) {
        bestScore = angle;
        best = c;
      }
    }
    if (!best) return dir.clone();
    const target = new THREE.Vector3(best.pos.x, 1.05, best.pos.z);
    const desired = target.sub(origin).normalize();
    const assist = game.input.touch ? 0.7 : game.input.aiming ? 0.45 : 0.15;
    return dir.clone().lerp(desired, assist).normalize();
  }

  trace(origin, dir, maxDist, ignore = null) {
    const game = this.game;
    let nearest = maxDist;
    let hit = null;

    // characters
    for (const c of [...game.peds, ...game.enemies]) {
      if (!c.alive || c === ignore) continue;
      const center = new THREE.Vector3(c.pos.x, c.pos.y + 1.02, c.pos.z);
      const t = raySphere(origin, dir, center, 0.48, nearest);
      if (t !== null && t < nearest) {
        nearest = t;
        hit = { type: 'character', object: c, distance: t, head: false };
      }
      // head sphere
      const headC = new THREE.Vector3(c.pos.x, c.pos.y + 1.62, c.pos.z);
      const th = raySphere(origin, dir, headC, 0.2, nearest);
      if (th !== null && th < nearest) {
        nearest = th;
        hit = { type: 'character', object: c, distance: th, head: true };
      }
    }

    // vehicles
    for (const v of game.vehicles.vehicles) {
      if (v.dead) continue;
      const rel = new THREE.Vector3().subVectors(origin, v.pos);
      const cos = Math.cos(-v.heading);
      const sin = Math.sin(-v.heading);
      const ox = rel.x * cos - rel.z * sin;
      const oz = rel.x * sin + rel.z * cos;
      const oy = rel.y;
      const dx = dir.x * cos - dir.z * sin;
      const dz = dir.x * sin + dir.z * cos;
      const dy = dir.y;
      const localOrigin = { x: ox, y: oy, z: oz };
      const localDir = { x: dx, y: dy, z: dz };
      const t = rayBox(
        localOrigin, localDir,
        { x: -v.stats.width / 2, y: 0.2, z: -v.stats.len / 2 },
        { x: v.stats.width / 2, y: v.stats.height + 0.2, z: v.stats.len / 2 },
        nearest
      );
      if (t !== null && t < nearest) {
        nearest = t;
        hit = { type: 'vehicle', object: v, distance: t };
      }
    }

    // buildings
    for (const c of game.world.colliders) {
      const t = rayBox(
        origin, dir,
        { x: c.minX, y: 0, z: c.minZ },
        { x: c.maxX, y: c.height, z: c.maxZ },
        nearest
      );
      if (t !== null && t < nearest) {
        nearest = t;
        hit = { type: 'world', distance: t };
      }
    }

    // ground
    if (dir.y < -0.0001) {
      const t = -origin.y / dir.y;
      if (t > 0 && t < nearest) {
        nearest = t;
        hit = { type: 'world', distance: t };
      }
    }

    if (!hit) return { hit: null, point: origin.clone().addScaledVector(dir, maxDist), distance: maxDist };
    const point = origin.clone().addScaledVector(dir, nearest);
    return { hit, point, distance: nearest };
  }

  tryFire(game) {
    const player = game.player;
    if (!player.alive || player.inVehicle) return;
    if (player.reloadTimer > 0) return;
    const w = player.weapon;
    if (player.fireCooldown > 0) return;
    if (w.ammo <= 0) {
      player.reload(game);
      return;
    }
    player.fireCooldown = w.rate;
    w.ammo--;
    game.hud.setWeapon(w);

    const cam = game.camera;
    const origin = cam.position.clone();
    const dir = cam.getWorldDirection(new THREE.Vector3());
    const aimDir = this.getAimDir(origin, dir);
    aimDir.normalize();

    const right = new THREE.Vector3().crossVectors(aimDir, cam.up).normalize();
    const up = new THREE.Vector3().crossVectors(right, aimDir).normalize();
    const spread = w.spread * (player.aiming ? 0.55 : 1) * (player.sprinting ? 1.8 : 1);
    if (player.moveSpeed > 4) spread *= 1.2;

    const muzzle = player.pos.clone();
    muzzle.y += 1.25;
    const fwd = new THREE.Vector3(Math.sin(player.heading), 0, Math.cos(player.heading));
    muzzle.addScaledVector(fwd, 0.45);
    muzzle.x += right.x * 0.22;
    muzzle.z += right.z * 0.22;

    let anyHit = false;
    let killed = false;

    for (let p = 0; p < w.pellets; p++) {
      const d = aimDir.clone();
      d.addScaledVector(right, (Math.random() - 0.5) * spread * 2);
      d.addScaledVector(up, (Math.random() - 0.5) * spread * 2);
      d.normalize();
      const result = this.trace(origin, d, w.range, player);
      const hit = result.hit;
      const end = result.point;
      if (hit) {
        if (hit.type === 'character') {
          const c = hit.object;
          const dmg = w.damage * (hit.head ? 2.2 : 1) * (p === 0 ? 1 : 0.9);
          const dead = c.damage(dmg, game, { bullet: true });
          anyHit = true;
          if (dead) killed = true;
          game.fx.blood(end);
          if (c.kind === 'gangster' || c.kind === 'cop') {
            if (dead) game.hud.showHit(true);
          }
          if (dead) {
            if (c.kind !== 'cop' && c.kind !== 'gangster') game.addWanted(1, '민간인 사살');
          } else if (c.kind !== 'cop' && c.kind !== 'gangster' && Math.random() < 0.4) {
            game.addWanted(1, '총격 사건');
          }
        } else if (hit.type === 'vehicle') {
          hit.object.damage(w.damage * 0.7, game, 'bullet');
          game.fx.sparks(end, null);
          anyHit = true;
          if (hit.object.isPolice) game.addWanted(1, '경찰차 공격');
        } else {
          game.fx.sparks(end, null);
        }
      }
      game.fx.tracer(muzzle, end, 0xffe3a0, 0.06);
    }

    if (anyHit) {
      game.hud.showHit(killed);
      this.lastHit = performance.now();
    }
    game.fx.burst(muzzle, { count: 3, color: 0xffd27f, speed: 2.2, life: 0.12, size: 0.3, gravity: 0, spread: 1 });
    game.fx.shake = Math.max(game.fx.shake, w.id === 'shotgun' ? 0.18 : w.id === 'smg' ? 0.05 : 0.09);
    game.audio.gunshot(w.id);
    game.onGunshot(player.pos);
    player.model.armR.rotation.x = -1.55;
    player.animate(0.016, 0, true);
  }

  enemyShoot(shooter, target, accuracy, damage) {
    const game = this.game;
    const player = game.player;
    if (!player.alive) return;
    const vehicle = player.vehicle;
    const targetPos = vehicle ? vehicle.pos.clone().add(new THREE.Vector3(0, 0.9, 0)) : player.pos.clone().add(new THREE.Vector3(0, 1.1, 0));
    const origin = shooter.pos.clone();
    origin.y += 1.25;
    const dir = targetPos.clone().sub(origin).normalize();

    const hitChance = clamp(accuracy, 0.05, 0.9);
    const willHit = Math.random() < hitChance;
    if (!willHit) {
      dir.x += (Math.random() - 0.5) * 0.16;
      dir.y += (Math.random() - 0.5) * 0.1;
      dir.z += (Math.random() - 0.5) * 0.16;
      dir.normalize();
    } else {
      dir.x += (Math.random() - 0.5) * 0.02;
      dir.y += (Math.random() - 0.5) * 0.02;
      dir.normalize();
    }
    const distance = 60;
    const result = this.trace(origin, dir, distance, shooter);
    const end = result.point;
    game.fx.tracer(origin, end, 0xffb36b, 0.09);
    game.fx.burst(origin, { count: 2, color: 0xffcf7a, speed: 1.2, life: 0.09, size: 0.22, gravity: 0, spread: 1 });
    game.audio.enemyShot(shooter.pos);

    if (willHit) {
      if (vehicle) {
        vehicle.damage(damage * 0.8, game, 'bullet');
        if (Math.random() < 0.25) player.damage(damage * 0.4, game, { bullet: true });
        game.fx.sparks(end, null);
      } else {
        player.damage(damage, game, { bullet: true });
        game.fx.blood(end);
        game.fx.shake = Math.max(game.fx.shake, 0.12);
      }
    } else {
      if (result.hit?.type === 'world') game.fx.sparks(end, null);
    }
  }
}

