const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

export class AudioSystem {
  constructor(game) {
    this.game = game;
    this.ctx = null;
    this.ready = false;
    this.master = null;
    this.noiseBuffer = null;
    this.engine = null;
    this.siren = null;
    this.sirenPhase = 0;
    this.lastFootstep = 0;
    this.enemyGunToggle = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.62;
    this.master.connect(this.ctx.destination);

    const len = this.ctx.sampleRate * 1.2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buf;
    this._buildEngine();
    this._buildSiren();
    this._buildAmbient();
    this.ready = true;
  }

  _noise(duration, gainValue, filterFreq, type = 'lowpass', pan = 0) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = filterFreq;
    filter.Q.value = 0.8;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gainValue, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(filter).connect(g);
    let node = g;
    if (pan !== 0) {
      const p = this.ctx.createStereoPanner();
      p.pan.value = clamp(pan, -1, 1);
      g.connect(p);
      node = p;
    }
    node.connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.05);
  }

  _tone(type, freq, duration, gainValue, opts = {}) {
    if (!this.ready) return;
    const t = this.ctx.currentTime + (opts.delay || 0);
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (opts.slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, opts.slideTo), t + duration);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gainValue, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    const filter = this.ctx.createBiquadFilter();
    filter.type = opts.filter || 'lowpass';
    filter.frequency.value = opts.cutoff || 1400;
    osc.connect(filter).connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + duration + 0.03);
  }

  _panFor(pos) {
    if (!pos || !this.game?.player) return 0;
    const cam = this.game.camera;
    const right = { x: Math.cos(this.game.cameraYaw), z: -Math.sin(this.game.cameraYaw) };
    const dx = pos.x - cam.position.x;
    const dz = pos.z - cam.position.z;
    const d = Math.hypot(dx, dz);
    if (d < 0.001) return 0;
    return ((dx * right.x + dz * right.z) / d) * 0.7;
  }

  _buildEngine() {
    const ctx = this.ctx;
    const gain = ctx.createGain();
    gain.gain.value = 0;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 700;
    filter.Q.value = 3;
    gain.connect(filter).connect(this.master);
    const osc1 = ctx.createOscillator();
    osc1.type = 'sawtooth';
    osc1.frequency.value = 55;
    const osc2 = ctx.createOscillator();
    osc2.type = 'square';
    osc2.frequency.value = 27.5;
    const g2 = ctx.createGain();
    g2.gain.value = 0.4;
    osc1.connect(gain);
    osc2.connect(g2).connect(gain);
    osc1.start();
    osc2.start();
    this.engine = { gain, filter, osc1, osc2 };
  }

  _buildSiren() {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.value = 720;
    const gain = ctx.createGain();
    gain.gain.value = 0;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 900;
    filter.Q.value = 2;
    osc.connect(filter).connect(gain).connect(this.master);
    osc.start();
    this.siren = { osc, gain };
  }

  _buildAmbient() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 260;
    const gain = ctx.createGain();
    gain.gain.value = 0.018;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
  }

  startEngine() {
    if (!this.ready) return;
    this.engine.gain.gain.cancelScheduledValues(this.ctx.currentTime);
    this.engine.gain.gain.setTargetAtTime(0.05, this.ctx.currentTime, 0.1);
  }

  stopEngine() {
    if (!this.ready) return;
    this.engine.gain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.12);
  }

  updateEngine(rpm, throttle) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const f = 48 + rpm * 155;
    this.engine.osc1.frequency.setTargetAtTime(f, t, 0.05);
    this.engine.osc2.frequency.setTargetAtTime(f * 0.5, t, 0.05);
    this.engine.filter.frequency.setTargetAtTime(420 + rpm * 1100, t, 0.08);
    this.engine.gain.gain.setTargetAtTime(0.028 + rpm * 0.05 + Math.max(0, throttle) * 0.012, t, 0.08);
  }

  updateSiren(distance, active) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    if (!active) {
      this.siren.gain.gain.setTargetAtTime(0, t, 0.2);
      return;
    }
    this.sirenPhase += 0.016;
    const f = 640 + Math.abs(Math.sin(this.sirenPhase * 2.4)) * 420;
    this.siren.osc.frequency.setTargetAtTime(f, t, 0.03);
    this.siren.gain.gain.setTargetAtTime(clamp(1 - distance / 130, 0, 1) * 0.035, t, 0.1);
  }

  gunshot(id) {
    if (!this.ready) return;
    if (id === 'shotgun') {
      this._noise(0.34, 0.4, 900, 'lowpass');
      this._tone('sine', 120, 0.22, 0.24, { slideTo: 45, cutoff: 400 });
      this._noise(0.1, 0.2, 3000, 'highpass');
    } else if (id === 'smg') {
      this._noise(0.09, 0.24, 2200, 'lowpass');
      this._tone('square', 220, 0.06, 0.1, { slideTo: 90, cutoff: 900 });
    } else {
      this._noise(0.16, 0.28, 1600, 'lowpass');
      this._tone('sine', 180, 0.12, 0.16, { slideTo: 70, cutoff: 600 });
    }
  }

  enemyShot(pos) {
    if (!this.ready) return;
    const d = this.game.player.pos.distanceTo(pos);
    const vol = clamp(1 - d / 90, 0.05, 1);
    const pan = this._panFor(pos);
    this.enemyGunToggle = !this.enemyGunToggle;
    if (this.enemyGunToggle) this._noise(0.1, 0.16 * vol, 1400, 'lowpass', pan);
    else this._tone('square', 160, 0.08, 0.05 * vol, { slideTo: 80, cutoff: 700, delay: 0 });
  }

  explosion(pos) {
    if (!this.ready) return;
    const d = this.game.player.pos.distanceTo(pos);
    const vol = clamp(1 - d / 130, 0.15, 1);
    const pan = this._panFor(pos);
    this._noise(0.9, 0.6 * vol, 500, 'lowpass', pan);
    this._tone('sine', 80, 1.0, 0.35 * vol, { slideTo: 24, cutoff: 300 });
    this._tone('sawtooth', 140, 0.4, 0.12 * vol, { slideTo: 40, cutoff: 800 });
  }

  crash(intensity) {
    if (!this.ready) return;
    const v = clamp(intensity / 20, 0.08, 0.5);
    this._noise(0.25, v, 1200, 'bandpass');
    this._tone('square', 95, 0.14, v * 0.3, { slideTo: 50, cutoff: 500 });
  }

  thud(pos) {
    if (!this.ready) return;
    const d = this.game.player.pos.distanceTo(pos);
    this._noise(0.18, clamp(1 - d / 40, 0, 1) * 0.2, 300);
  }

  footstep(run) {
    if (!this.ready) return;
    const now = performance.now();
    if (now - this.lastFootstep < 180) return;
    this.lastFootstep = now;
    this._noise(0.07, run ? 0.035 : 0.022, run ? 900 : 600, 'bandpass');
  }

  setFootstepsMoving() {}

  jump() {
    this._tone('sine', 200, 0.12, 0.02, { slideTo: 120 });
  }

  reload() {
    if (!this.ready) return;
    this._tone('square', 700, 0.03, 0.05, { cutoff: 2000 });
    setTimeout(() => this._tone('square', 480, 0.04, 0.05, { cutoff: 1800 }), 130);
    setTimeout(() => this._tone('square', 900, 0.03, 0.04, { cutoff: 2200 }), 320);
  }

  click() {
    this._tone('square', 1100, 0.025, 0.03, { cutoff: 2500 });
  }

  horn() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    for (const f of [330, 415]) {
      const osc = this.ctx.createOscillator();
      osc.type = 'square';
      osc.frequency.value = f;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.045, t + 0.02);
      g.gain.setValueAtTime(0.045, t + 0.35);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 1200;
      osc.connect(filter).connect(g).connect(this.master);
      osc.start(t);
      osc.stop(t + 0.55);
    }
  }

  pedScream(pos) {
    if (!this.ready) return;
    const d = this.game.player.pos.distanceTo(pos);
    const vol = clamp(1 - d / 45, 0, 1);
    this._tone('sawtooth', 700 + Math.random() * 240, 0.18, 0.018 * vol, { slideTo: 420, cutoff: 1400 });
  }

  playerHit() {
    if (!this.ready) return;
    this._noise(0.16, 0.12, 500);
    this._tone('sine', 90, 0.2, 0.08, { slideTo: 45 });
  }

  wanted() {
    if (!this.ready) return;
    this._tone('sawtooth', 560, 0.12, 0.04, { slideTo: 820, cutoff: 1400 });
    setTimeout(() => this._tone('sawtooth', 820, 0.18, 0.04, { slideTo: 560, cutoff: 1400 }), 130);
  }

  missionPassed() {
    if (!this.ready) return;
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) => this._tone('triangle', f, 0.32, 0.06, { delay: i * 0.13, cutoff: 3000 }));
  }

  missionFailed() {
    if (!this.ready) return;
    const notes = [392, 349.23, 261.63];
    notes.forEach((f, i) => this._tone('sawtooth', f, 0.35, 0.045, { delay: i * 0.16, cutoff: 1200 }));
  }

  wasted() {
    if (!this.ready) return;
    this._tone('sine', 120, 1.6, 0.1, { slideTo: 35, cutoff: 300 });
    this._noise(1.2, 0.08, 300);
  }

  update(dt) {
    if (this.radio) this.radio.update(dt);
  }
}

/* ------------------------------------------------------------------ */
/* Radio - tiny procedural stations                                    */
/* ------------------------------------------------------------------ */

const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

const STATIONS = [
  {
    name: 'LOS SANTOS ROCK RADIO',
    bpm: 112,
    bass: [0, 0, 5, 0, 7, 0, 5, 3, 0, 0, 5, 0, 8, 7, 5, 3],
    lead: [12, null, null, 15, null, 12, null, null, 17, null, 15, null, 12, null, 10, null],
    root: 33,
    mode: 'rock',
  },
  {
    name: 'NON-STOP POP',
    bpm: 118,
    bass: [0, 0, 7, 7, 5, 5, 3, 3, 0, 0, 7, 7, 10, 10, 8, 7],
    lead: [24, 19, 22, 26, 19, 22, 24, 27, 26, 22, 19, 24, 27, 24, 22, 19],
    root: 45,
    mode: 'pop',
  },
  {
    name: 'WEST COAST CLASSICS',
    bpm: 92,
    bass: [0, null, 0, 7, null, 5, null, 3, 0, null, 0, 7, null, 10, 8, 7],
    lead: [12, null, 15, null, 19, null, 15, null, 12, null, 17, null, 15, null, 10, null],
    root: 36,
    mode: 'classic',
  },
];

export class Radio {
  constructor(audio) {
    this.audio = audio;
    this.enabled = false;
    this.station = 0;
    this.step = 0;
    this.nextTime = 0;
    this.ctx = null;
    this.bus = null;
    this.timer = 0;
  }

  _ensure() {
    if (!this.audio.ready) return false;
    if (!this.bus) {
      const ctx = this.audio.ctx;
      this.ctx = ctx;
      this.bus = ctx.createGain();
      this.bus.gain.value = 0;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 2600;
      this.bus.connect(filter).connect(this.audio.master);
    }
    return true;
  }

  start() {
    if (!this._ensure()) return;
    this.enabled = true;
    this.step = 0;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.bus.gain.setTargetAtTime(0.18, this.ctx.currentTime, 0.4);
    this.audio.game.hud.showRadio(STATIONS[this.station].name);
  }

  stop() {
    if (!this.bus) return;
    this.enabled = false;
    this.bus.gain.setTargetAtTime(0, this.ctx.currentTime, 0.25);
  }

  next() {
    if (!this.enabled) return;
    this.station = (this.station + 1) % STATIONS.length;
    this.step = 0;
    this.nextTime = this.ctx.currentTime + 0.05;
    this.audio.game.hud.showRadio(STATIONS[this.station].name);
  }

  _note(type, freq, time, dur, vol, cutoff = 1800) {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(vol, time + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = cutoff;
    osc.connect(filter).connect(g).connect(this.bus);
    osc.start(time);
    osc.stop(time + dur + 0.02);
  }

  _drum(time, kind) {
    const ctx = this.ctx;
    if (kind === 'kick') {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(130, time);
      osc.frequency.exponentialRampToValueAtTime(42, time + 0.14);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.5, time);
      g.gain.exponentialRampToValueAtTime(0.0001, time + 0.18);
      osc.connect(g).connect(this.bus);
      osc.start(time);
      osc.stop(time + 0.2);
      return;
    }
    const src = ctx.createBufferSource();
    src.buffer = this.audio.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = kind === 'snare' ? 'bandpass' : 'highpass';
    filter.frequency.value = kind === 'snare' ? 1800 : 7000;
    const g = ctx.createGain();
    g.gain.setValueAtTime(kind === 'snare' ? 0.22 : 0.08, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + (kind === 'snare' ? 0.13 : 0.04));
    src.connect(filter).connect(g).connect(this.bus);
    src.start(time);
    src.stop(time + 0.16);
  }

  update() {
    if (!this.enabled || !this.ctx) return;
    const st = STATIONS[this.station];
    const stepDur = 60 / st.bpm / 2;
    const now = this.ctx.currentTime;
    if (this.nextTime < now) this.nextTime = now + 0.05;
    while (this.nextTime < now + 0.25) {
      const s = this.step;
      const bassNote = st.bass[s];
      if (bassNote !== null && bassNote !== undefined) {
        this._note('sawtooth', midi(st.root + bassNote), this.nextTime, stepDur * 0.9, 0.12, 700);
        this._note('sine', midi(st.root + bassNote - 12), this.nextTime, stepDur * 0.9, 0.1, 500);
      }
      const lead = st.lead[s];
      if (lead !== null && lead !== undefined) {
        this._note(st.mode === 'pop' ? 'square' : 'triangle', midi(st.root + lead), this.nextTime, stepDur * 0.7, st.mode === 'pop' ? 0.035 : 0.05, 2400);
      }
      if (st.mode === 'rock') {
        if (s % 4 === 0) this._drum(this.nextTime, 'kick');
        if (s % 4 === 2) this._drum(this.nextTime, 'snare');
        if (s % 2 === 0) this._drum(this.nextTime, 'hat');
        if (s % 8 === 0) {
          this._note('sawtooth', midi(st.root + 12 + st.bass[s]), this.nextTime, stepDur * 3.6, 0.028, 1200);
          this._note('sawtooth', midi(st.root + 19 + st.bass[s]), this.nextTime, stepDur * 3.6, 0.022, 1200);
        }
      } else if (st.mode === 'pop') {
        if (s % 4 === 0) this._drum(this.nextTime, 'kick');
        if (s % 4 === 2) this._drum(this.nextTime, 'snare');
        if (s % 2 === 0) this._drum(this.nextTime, 'hat');
      } else {
        if (s === 0 || s === 3 || s === 8 || s === 10) this._drum(this.nextTime, 'kick');
        if (s === 4 || s === 12) this._drum(this.nextTime, 'snare');
        if (s % 2 === 0) this._drum(this.nextTime, 'hat');
      }
      this.nextTime += stepDur;
      this.step = (s + 1) % 16;
    }
  }
}

import * as THREE from 'three';
import { Cop } from './characters.js';
import { Vehicle } from './vehicles.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);

export class PoliceSystem {
  constructor(game) {
    this.game = game;
    this.cops = [];
    this.cars = [];
    this.spawnTimer = 0;
    this.copTimer = 0;
    this.evading = false;
    this.evadeTimer = 0;
    this.starTimer = 0;
    this.clearTimer = 0;
    this.sirenTime = 0;
    this.carFireTimers = new Map();
    this.lastWanted = 0;
  }

  resetEvasion() {
    this.evading = false;
    this.evadeTimer = 0;
    this.starTimer = 0;
  }

  onWantedRaised() {
    this.resetEvasion();
    this.lastWanted = this.game.wanted;
    this.clearTimer = 0;
  }

  update(dt, game) {
    const wanted = game.wanted;
    const player = game.player;
    if (wanted <= 0) {
      this.evading = false;
      this.evadeTimer = 0;
      if (this.cars.length || this.cops.length) {
        this.clearTimer += dt;
        if (this.clearTimer > 10) this._clearAll(game, true);
      }
      game.audio.updateSiren(999, false);
      return;
    }
    this.clearTimer = 0;

    // --- spawning ---
    this.spawnTimer -= dt;
    const desiredCars = Math.min(4, wanted);
    const activeCars = this.cars.filter((v) => !v.dead && !v.isPlayer);
    if (this.spawnTimer <= 0 && activeCars.length < desiredCars) {
      this.spawnTimer = rand(2.4, 4.5) - Math.min(1.2, wanted * 0.2);
      this._spawnCopCar(game);
    }

    this.copTimer -= dt;
    const desiredCops = wanted >= 1 ? Math.min(9, 1 + wanted * 2) : 0;
    const activeCops = this.cops.filter((c) => c.alive);
    if (this.copTimer <= 0 && activeCops.length < desiredCops) {
      this.copTimer = rand(1.6, 3.2);
      this._spawnCop(game);
    }

    // --- cops chase & shoot (movement handled in main for all enemies) ---
    for (const c of this.cops) {
      if (!c.alive) continue;
      c.accuracy = 0.34 + Math.min(wanted, 5) * 0.045;
      c.damageAmount = 7 + Math.min(wanted, 5);
    }

    // --- cop cars ---
    let nearestCar = null;
    let nearestDist = 1e9;
    for (const v of this.cars) {
      if (v.dead) continue;
      if (v.isPlayer) continue;
      v.ai = { type: 'chase', target: player };
      const d = Math.hypot(v.pos.x - player.pos.x, v.pos.z - player.pos.z);
      if (d < nearestDist) { nearestDist = d; nearestCar = v; }
      if (d > 280) {
        const spot = game.vehicles._roadSpawn(70, 140, player.pos);
        v.group.position.set(spot.x, 0, spot.z);
        v.heading = spot.heading;
        v.group.rotation.y = spot.heading;
        v.speed = 10;
      }
      // drive-by shots
      let timer = this.carFireTimers.get(v) ?? rand(0.5, 1.4);
      timer -= dt;
      if (timer <= 0 && d < 42 && d > 8) {
        timer = rand(1.0, 1.8);
        this._copCarShoot(v, game, d);
      }
      this.carFireTimers.set(v, timer);
    }

    // siren
    if (nearestCar && nearestDist < 220) {
      game.audio.updateSiren(nearestDist, true);
    } else {
      game.audio.updateSiren(999, false);
    }

    // --- evasion ---
    let closestCop = 1e9;
    for (const c of this.cops) {
      if (c.alive) closestCop = Math.min(closestCop, Math.hypot(c.pos.x - player.pos.x, c.pos.z - player.pos.z));
    }
    for (const v of this.cars) {
      if (!v.dead && !v.isPlayer) closestCop = Math.min(closestCop, Math.hypot(v.pos.x - player.pos.x, v.pos.z - player.pos.z));
    }

    if (closestCop > 55) {
      this.evadeTimer += dt;
      if (this.evadeTimer > 6) {
        if (!this.evading) {
          this.evading = true;
          this.starTimer = 0;
          game.notify('수배 회피 중', '경찰의 시야에서 벗어났습니다.', 'police');
        }
        this.starTimer += dt;
        if (this.starTimer > 5.5) {
          this.starTimer = 0;
          game.wanted = Math.max(0, game.wanted - 1);
          if (game.wanted > 0) {
            game.notify('수배 레벨 감소', `수배 ${game.wanted}단계`, 'police');
          } else {
            game.onWantedCleared();
          }
        }
      }
    } else {
      if (closestCop < 40) {
        this.evadeTimer = 0;
        this.evading = false;
      }
    }

    // dead cleanup
    for (const v of this.cars) {
      if (v.dead) {
        const i = this.cars.indexOf(v);
        if (i >= 0) this.cars.splice(i, 1);
      }
    }
    for (const c of this.cops) {
      if (!c.alive) {
        if (c.deadTime === 0) c.deadTime = 0.01;
      }
    }
  }

  _spawnCopCar(game) {
    const player = game.player;
    const spot = game.vehicles._roadSpawn(95, 190, player.pos);
    const v = game.vehicles.add({ x: spot.x, z: spot.z, heading: spot.heading, type: 'police' });
    v.ai = { type: 'chase', target: player };
    v.isPolice = true;
    this.cars.push(v);
    game.audio.wanted();
  }

  _spawnCop(game) {
    const player = game.player;
    let x = null;
    let z = null;
    for (let tries = 0; tries < 30; tries++) {
      const spot = game.vehicles._roadSpawn(34, 70, player.pos);
      const d = Math.hypot(spot.x - player.pos.x, spot.z - player.pos.z);
      if (d > 30) {
        x = spot.x;
        z = spot.z;
        break;
      }
    }
    if (x === null) {
      const p = game.world.randomSidewalk();
      x = p.x;
      z = p.z;
    }
    const heading = Math.atan2(player.pos.x - x, player.pos.z - z);
    const cop = new Cop(game.scene, { x, z, heading, health: 100 });
    game.enemies.push(cop);
    this.cops.push(cop);
  }

  _copCarShoot(car, game, dist) {
    const player = game.player;
    const target = player.vehicle ? player.vehicle.pos : player.pos;
    if (game.world.lineBlocked(car.pos.x, car.pos.z, target.x, target.z)) return;
    const from = new THREE.Vector3(car.pos.x, 1.6, car.pos.z);
    const to = new THREE.Vector3(target.x, player.vehicle ? 1.0 : 1.15, target.z);
    const dir = to.clone().sub(from).normalize();
    const hit = Math.random() < clamp(0.42 - dist / 160, 0.12, 0.42);
    if (!hit) {
      dir.x += (Math.random() - 0.5) * 0.16;
      dir.z += (Math.random() - 0.5) * 0.16;
      dir.normalize();
    }
    const end = to.clone().addScaledVector(dir, 10);
    game.fx.tracer(from, hit ? to : end, 0xffc07a, 0.08);
    game.fx.burst(from, { count: 2, color: 0xffd27f, speed: 1.4, life: 0.08, size: 0.24, gravity: 0, spread: 1 });
    game.audio.enemyShot(car.pos);
    if (hit) {
      if (player.vehicle) {
        player.vehicle.damage(5, game, 'bullet');
        if (Math.random() < 0.2) player.damage(4, game, { bullet: true });
      } else {
        player.damage(5, game, { bullet: true });
        game.fx.blood(to);
      }
    }
  }

  _clearAll(game, silent) {
    for (const v of this.cars) {
      if (v.isPlayer) continue;
      v.ai = null;
      v.brake = 1;
      const i = game.vehicles.vehicles.indexOf(v);
      if (i >= 0) game.vehicles.vehicles.splice(i, 1);
      game.scene.remove(v.group);
    }
    this.cars = [];
    for (const c of this.cops) {
      if (c.alive) {
        const i = game.enemies.indexOf(c);
        if (i >= 0) game.enemies.splice(i, 1);
        c.remove();
      }
    }
    this.cops = [];
    this.carFireTimers.clear();
    if (!silent) game.audio.updateSiren(999, false);
  }

  onPlayerDeath() {
    this._clearAll(this.game, true);
  }
}

import * as THREE from 'three';
import { Gangster } from './characters.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rand = (a, b) => a + Math.random() * (b - a);

const GARAGE = { x: -78, z: -39 };
const POLICE_TRAP = { x: 0, z: 78 };
const BANK = { x: 78, z: 0 };
const LOCKUP = { x: -234, z: 234 };

function createMarker(scene) {
  const group = new THREE.Group();
  group.visible = false;

  const ringMat = new THREE.MeshBasicMaterial({ color: 0xf4c542, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false });
  const ring = new THREE.Mesh(new THREE.RingGeometry(1.5, 2.15, 40), ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.16;
  group.add(ring);

  const innerRing = new THREE.Mesh(new THREE.RingGeometry(0.6, 0.78, 28), ringMat);
  innerRing.rotation.x = -Math.PI / 2;
  innerRing.position.y = 0.17;
  group.add(innerRing);

  const beamMat = new THREE.MeshBasicMaterial({
    color: 0xf4c542, transparent: true, opacity: 0.1, side: THREE.DoubleSide,
    depthWrite: false, blending: THREE.AdditiveBlending,
  });
  const beam = new THREE.Mesh(new THREE.CylinderGeometry(2.05, 2.2, 9, 24, 1, true), beamMat);
  beam.position.y = 4.5;
  group.add(beam);

  const diamond = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.48, 0),
    new THREE.MeshBasicMaterial({ color: 0xffdb5c, toneMapped: false })
  );
  diamond.position.y = 3.4;
  group.add(diamond);

  const light = new THREE.PointLight(0xffcc55, 2.4, 14, 1.4);
  light.position.y = 1.6;
  group.add(light);

  scene.add(group);
  return { group, ring, innerRing, beam, diamond, light };
}

export class MissionManager {
  constructor(game) {
    this.game = game;
    this.marker = createMarker(game.scene);
    this.activeMarker = null;
    this.targetVehicle = null;
    this.state = 'idle';
    this.delay = 6;
    this.index = 0;
    this.stage = 0;
    this.timer = 0;
    this.progress = 0;
    this.gangsters = [];
    this.markerTime = 0;
    this.done = false;
    this.lastHint = 0;
    this.hintShown = false;
    this.cooldown = 0;
    this.pendingIndex = 0;
    this.mode = 'advance';
    this.parkingBlock = game.world.parkingBlocks.find((b) => b.i > -2 && b.j > -2) || null;
    this.parkingSpot = this.parkingBlock
      ? { x: this.parkingBlock.cx, z: this.parkingBlock.cz }
      : { x: 78 * 2, z: 78 * 1 };
    this.bankProgress = 0;
  }

  start() {
    this.state = 'idle';
    this.delay = 6;
    this.index = 0;
    this.done = false;
    if (!this.game.parkingBlock) {
      const b = this.game.world.parkingBlocks.find((b) => b.i > -2 && b.j > -2);
      if (b) this.parkingSpot = { x: b.cx, z: b.cz };
    }
  }

  setMarker(pos, radius = 0) {
    if (!pos) {
      this.marker.group.visible = false;
      this.activeMarker = null;
      return;
    }
    this.marker.group.visible = true;
    this.marker.group.position.set(pos.x, 0, pos.z);
    this.activeMarker = { x: pos.x, z: pos.z, radius };
  }

  update(dt) {
    const game = this.game;
    this.markerTime += dt;
    if (this.marker.group.visible) {
      this.marker.diamond.rotation.y += dt * 1.4;
      this.marker.diamond.position.y = 3.3 + Math.sin(this.markerTime * 2.2) * 0.18;
      this.marker.ring.rotation.z += dt * 0.5;
      this.marker.innerRing.rotation.z -= dt * 0.8;
      this.marker.beam.material.opacity = 0.08 + Math.sin(this.markerTime * 2.4) * 0.03;
    }

    if (this.state === 'idle') {
      this.delay -= dt;
      if (this.delay <= 0) this.startMission(this.index);
      return;
    }
    if (this.state === 'cooldown') {
      this.cooldown -= dt;
      if (this.cooldown <= 0) {
        if (this.mode === 'advance') {
          this.index++;
          if (this.index >= 4) {
            this.done = true;
            this.state = 'done';
            game.hud.setObjective('');
            game.hud.subtitle('모든 임무 완료. 이제 로스 산토스는 당신의 놀이터입니다.', 5);
            game.notify('FREEROAM', '모든 임무를 완료했습니다. 자유롭게 도시를 누비세요.', 'money-note');
            return;
          }
        }
        this.startMission(this.index);
      }
      return;
    }
    if (this.state !== 'active') return;
    if (!game.player.alive) return;

    const player = game.player;
    const targetPos = player.vehicle ? player.vehicle.pos : player.pos;
    const distPlayer = (p) => Math.hypot(targetPos.x - p.x, targetPos.z - p.z);

    switch (this.index) {
      case 0:
        this._updateRepo(dt, distPlayer, player);
        break;
      case 1:
        this._updateShakedown(dt, distPlayer, player);
        break;
      case 2:
        this._updateHeat(dt, distPlayer, player);
        break;
      case 3:
        this._updateHeist(dt, distPlayer, player);
        break;
      default:
        break;
    }
  }

  startMission(i) {
    const game = this.game;
    this.index = i;
    this.state = 'active';
    this.stage = 0;
    this.timer = 0;
    this.progress = 0;
    this.bankProgress = 0;
    this.hintShown = false;
    this.markerTime = 0;
    game.hud.hideBig();
    this.gangsters.forEach((g) => {
      const idx = game.enemies.indexOf(g);
      if (idx >= 0) game.enemies.splice(idx, 1);
      g.remove();
    });
    this.gangsters = [];

    if (i === 0) {
      let car = this.targetVehicle;
      if (!car || car.dead) {
        car = game.vehicles.add({ x: 152, z: 174, heading: Math.PI, type: 'sports', color: 0xd97a24 });
        this.targetVehicle = car;
      }
      this.setMarker({ x: car.pos.x, z: car.pos.z }, 5);
      game.hud.setObjective('LAMAR의 일감 — 노란 마커로 이동해 회수 차량을 확보하세요');
      game.hud.subtitle('LAMAR: 어이, 첫 일감이다. 그 스포츠카, 회수해서 차고지로 가져와.', 4.6);
      game.notify('새 임무 · REPOSSESSION', '노란 마커로 가서 차량을 회수하세요.', '');
    } else if (i === 1) {
      this.setMarker(this.parkingSpot, 5);
      game.hud.setObjective('SHAKEDOWN — 주차장으로 이동하세요');
      game.hud.subtitle('LAMAR: 조직원들이 네 구역에서 장사를 벌이고 있어. 정리해 줘.', 4.6);
      game.notify('새 임무 · SHAKEDOWN', '주차장에서 조직원 4명을 제거하세요.', '');
    } else if (i === 2) {
      this.setMarker(POLICE_TRAP, 6);
      game.hud.setObjective('HEAT — 경찰의 함정으로 이동하세요');
      game.hud.subtitle('LAMAR: 경찰이 널 찾고 있어. 일부러 걸려서 실력을 보여줘.', 4.6);
      game.notify('새 임무 · HEAT', '경찰을 유인해 45초간 버티세요.', 'police');
    } else if (i === 3) {
      this.setMarker(BANK, 6);
      game.hud.setObjective('THE BIG SCORE — 은행으로 이동하세요');
      game.hud.subtitle('LAMAR: 큰 거 한 건 가자. 은행 금고를 털고 차로 탈출해.', 4.8);
      game.notify('새 임무 · THE BIG SCORE', '은행 금고를 털고 현금을 락업으로 운반하세요.', 'money-note');
    }
  }

  _updateRepo(dt, dist, player) {
    const game = this.game;
    const car = this.targetVehicle;
    if (!car || car.dead) {
      this.fail('회수 차량이 파괴되었습니다.');
      return;
    }
    if (this.stage === 0) {
      this.setMarker({ x: car.pos.x, z: car.pos.z }, 5);
      if (dist({ x: car.pos.x, z: car.pos.z }) < 7 && !player.vehicle) {
        if (!this.hintShown) {
          this.hintShown = true;
          game.hud.subtitle('차량에 다가가 F 를 누르면 훔칠 수 있습니다.', 3.2);
        }
      }
      if (player.vehicle === car) {
        this.stage = 1;
        this.setMarker(GARAGE, 7);
        game.hud.setObjective('회수 차량을 차고지로 배달하세요');
        game.hud.subtitle('차고지까지 운전하세요. 경찰에 걸리지 않게 조심하고.', 3.4);
        game.notify('차량 확보', '차고지로 이동하세요.', '');
      } else if (player.vehicle && player.vehicle !== car) {
        if (!this.hintShown) {
          this.hintShown = true;
          game.hud.subtitle('회수 대상 차량은 주황색 스포츠카입니다.', 2.8);
        }
      }
    } else {
      this.setMarker(GARAGE, 7);
      if (dist(GARAGE) < 9 && player.vehicle === car) {
        this.pass(2500, 'REPOSSESSION');
      }
      if (dist(GARAGE) < 9 && player.vehicle !== car) {
        if (!this.hintShown) {
          this.hintShown = true;
          game.hud.subtitle('회수 차량을 차고지로 가져와야 합니다.', 2.8);
        }
      }
    }
  }

  _updateShakedown(dt, dist, player) {
    const game = this.game;
    if (this.stage === 0) {
      if (dist(this.parkingSpot) < 8) {
        this.stage = 1;
        this.setMarker(null);
        this.spawnGangsters();
        game.hud.setObjective('조직원 4명을 제거하세요 (0/4)');
        game.hud.subtitle('LAMAR: 조심해, 총 들고 있어. 엄폐물을 활용해.', 3.6);
        game.notify('교전 발생', '조직원 4명이 당신을 노리고 있습니다.', 'police');
        game.audio.wanted();
      }
      return;
    }
    const alive = this.gangsters.filter((g) => g.alive).length;
    const killed = this.gangsters.length - alive;
    game.hud.setObjective(`조직원 ${this.gangsters.length}명을 제거하세요 (${killed}/${this.gangsters.length})`);
    if (alive === 0) this.pass(4000, 'SHAKEDOWN');
  }

  _updateHeat(dt, dist, player) {
    const game = this.game;
    if (this.stage === 0) {
      if (dist(POLICE_TRAP) < 9) {
        this.stage = 1;
        this.timer = 45;
        this.setMarker(null);
        game.raiseWanted(2, '함정에 걸렸습니다', true);
        game.hud.setObjective('경찰의 공격을 45초간 버티세요');
        game.hud.subtitle('45초만 버티면 돼. 차를 훔쳐 도망다녀도 좋아.', 3.6);
      }
      return;
    }
    this.timer -= dt;
    const left = Math.max(0, Math.ceil(this.timer));
    game.hud.setObjective(`경찰의 공격을 버티세요 — ${left}초`);
    if (game.wanted === 0 && left < 40) {
      game.raiseWanted(2, '경찰이 다시 몰려옵니다', true);
    }
    if (game.player.health < 25) game.player.health = Math.min(100, game.player.health + dt * 1.4);
    if (this.timer <= 0) {
      game.clearWanted();
      this.pass(6000, 'HEAT');
    }
  }

  _updateHeist(dt, dist, player) {
    const game = this.game;
    if (this.stage === 0) {
      if (dist(BANK) < 9) {
        this.stage = 1;
        this.bankProgress = 0;
        this.setMarker(null);
        game.hud.setObjective('은행 금고를 털어라');
        game.hud.subtitle('금고 앞에서 잠시 기다리면 현금을 확보할 수 있습니다.', 3.4);
        game.notify('은행 습격', '금고를 털고 차량으로 탈출하세요.', 'money-note');
      }
      return;
    }
    if (this.stage === 1) {
      const bankDist = Math.hypot(player.pos.x - BANK.x, player.pos.z - BANK.z);
      if (bankDist < 10) {
        this.bankProgress += dt;
        const pct = Math.min(100, Math.round((this.bankProgress / 3.2) * 100));
        game.hud.setObjective(`은행 금고를 터는 중... ${pct}%`);
        if (this.bankProgress >= 3.2) {
          this.stage = 2;
          game.addMoney(1500);
          game.raiseWanted(3, '은행 강도', true);
          this.setMarker(LOCKUP, 8);
          game.hud.setObjective('현금을 차량에 싣고 락업으로 이동하세요');
          game.hud.subtitle('차량을 찾아 락업까지 도주하세요. 경찰이 출동했습니다.', 4);
          game.notify('현금 확보', '$1,500 확보 · 락업으로 이동하세요.', 'money-note');
        }
      } else {
        game.hud.setObjective('은행 금고 앞으로 돌아가세요');
      }
      return;
    }
    if (this.stage === 2) {
      this.setMarker(LOCKUP, 8);
      if (player.vehicle && dist(LOCKUP) < 10) {
        game.clearWanted();
        this.pass(25000, 'THE BIG SCORE');
      } else if (!player.vehicle && dist(LOCKUP) < 10) {
        if (!this.hintShown) {
          this.hintShown = true;
          game.hud.subtitle('현금을 차량에 싣고 와야 합니다. 근처 차량을 훔치세요.', 3.2);
        }
      }
    }
  }

  spawnGangsters() {
    const game = this.game;
    const base = this.parkingSpot;
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2 + rand(-0.3, 0.3);
      let x = base.x + Math.cos(a) * rand(9, 15);
      let z = base.z + Math.sin(a) * rand(9, 15);
      const res = game.world.resolveCircle(x, z, 0.5);
      x = res.x;
      z = res.z;
      const g = new Gangster(game.scene, {
        x, z, heading: Math.atan2(base.x - x, base.z - z),
        health: 110,
      });
      game.enemies.push(g);
      this.gangsters.push(g);
    }
  }

  pass(reward, title) {
    const game = this.game;
    this.state = 'cooldown';
    this.mode = 'advance';
    this.cooldown = 9;
    this.setMarker(null);
    this.targetVehicle = null;
    game.addMoney(reward);
    game.hud.setObjective('', true);
    game.hud.showBig('MISSION PASSED', `+$${reward.toLocaleString('en-US')}`, 'pass', 4.6);
    game.hud.subtitle(`${title} 완료 · 다음 일감이 곧 들어옵니다.`, 4);
    game.notify('임무 완료 · ' + title, `보상 +$${reward.toLocaleString('en-US')}`, 'money-note');
    game.audio.missionPassed();
    game.fx.shake = 0.12;
    if (this.gangsters.length) {
      // leave bodies, clear references
      this.gangsters = this.gangsters.filter((g) => g.alive);
    }
  }

  fail(reason) {
    if (this.state !== 'active') return;
    const game = this.game;
    this.state = 'cooldown';
    this.mode = 'retry';
    this.cooldown = 8;
    this.setMarker(null);
    this.targetVehicle = null;
    game.hud.setObjective('', true);
    game.hud.showBig('MISSION FAILED', reason, '', 4);
    game.hud.subtitle('잠시 후 임무를 다시 시작할 수 있습니다.', 3);
    game.notify('임무 실패', reason, 'police');
    game.audio.missionFailed();
    for (const g of this.gangsters) {
      const idx = game.enemies.indexOf(g);
      if (idx >= 0) game.enemies.splice(idx, 1);
      g.remove();
    }
    this.gangsters = [];
  }

  onPlayerDeath() {
    if (this.state === 'active') this.fail('사망했습니다.');
  }

  onWantedCleared() {
    if (this.state === 'active' && this.index === 2 && this.stage === 1 && this.timer > 0) {
      game_heatContinue(this.game);
    }
    if (this.game.wanted === 0 && this.state === 'active' && this.stage === 2) {
      this.game.notify('수배 해제', '경찰이 수색을 포기했습니다. 락업으로 이동하세요.', '');
    }
  }
}

function game_heatContinue(game) {
  game.hud.subtitle('경찰이 잠시 후퇴했습니다. 남은 시간을 버티세요.', 2.4);
}

